window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[45]={"id":"045","numero":45,"titre":"Maladies génétiques","strategie":{"urgence":"\n<p><strong>Pas d'<span class=\"kw-alerte\">urgence</span> vitale propre au champ « maladies génétiques ».</strong> L'urgence dépend de la pathologie sous-jacente :</p>\n<ul>\n  <li><strong>Trisomie 21</strong> à la naissance → rechercher en <span class=\"kw-alerte\">urgence</span> : <span class=\"kw-etio\">CAV / cardiopathie</span>, <span class=\"kw-etio\">atrésie duodénale</span>, <span class=\"kw-etio\">imperforation anale</span>, <span class=\"kw-etio\">iléus méconial</span>, <span class=\"kw-clinique\">hypotonie sévère</span>.</li>\n  <li><strong>Mucoviscidose</strong> néonatale → <span class=\"kw-alerte\">iléus méconial</span> (occlusion par méconium visqueux → <span class=\"kw-ttt\">lavage</span> ± <span class=\"kw-ttt\">chirurgie</span>), <span class=\"kw-alerte\">ictère cholestatique rétentionnel</span>, <span class=\"kw-alerte\">déshydratation hyponatrémique avec coup de chaleur</span> ⭐ (tombé en annale).</li>\n  <li><strong>Exacerbation respiratoire mucoviscidose</strong> → <span class=\"kw-ttt\">ATB ciblée <span class=\"kw-chiffre\">2–3 sem</span></span> (per os / inhalée / IV) selon <span class=\"kw-bio\">ECBC</span>, <span class=\"kw-ttt\">kiné quotidienne intensifiée</span>.</li>\n  <li><strong><span class=\"kw-clinique\">DPN</span> positif</strong> → <span class=\"kw-ttt\">IMG</span> possible jusqu'au terme (T21 : choisie dans &gt; <span class=\"kw-chiffre\">95 %</span> des cas).</li>\n</ul>","hospit":"\n<p><strong>Filière diagnostique anténatale :</strong></p>\n<ul>\n  <li><span class=\"kw-def\">Suivi</span> obstétrical + <span class=\"kw-imagerie\">échographies de référence</span> (T1 <span class=\"kw-chiffre\">11–13 SA+6</span>, T2 <span class=\"kw-chiffre\">22 SA</span>, T3 <span class=\"kw-chiffre\">32 SA</span>) + <span class=\"kw-bio\">marqueurs sériques</span>.</li>\n  <li><strong>CPDPN</strong> (Centre Pluridisciplinaire de Diagnostic Prénatal) si signes d'appel ou risque calculé élevé → <span class=\"kw-def\">DPI</span> / <span class=\"kw-ttt\">amniocentèse</span> / <span class=\"kw-ttt\">choriocentèse</span>.</li>\n</ul>\n<p><strong>Filière postnatale :</strong></p>\n<ul>\n  <li><strong>Consultation de <span class=\"kw-etio\">génétique</span></strong> (généticien clinique + conseiller en génétique) → arbre généalogique, conseil, signature des consentements.</li>\n  <li><strong>CRCM</strong> régional (Centre de Ressources et de Compétences pour la Mucoviscidose) après <span class=\"kw-bio\">dépistage Guthrie</span> positif.</li>\n  <li><strong>CRMR Trisomie 21</strong> et <strong>CRMR X fragile</strong> pour le <span class=\"kw-def\">suivi</span> multidisciplinaire (filière AnDDI-Rares).</li>\n  <li>Médecin traitant / pédiatre → coordination du <span class=\"kw-def\">suivi</span> annuel.</li>\n</ul>","redflags":"\n<ul>\n  <li><span class=\"kw-alerte\">Bronchiolite récidivante + cassure pondérale</span> ⭐ (annale) → évoquer la <strong>mucoviscidose</strong>.</li>\n  <li><span class=\"kw-alerte\">Déshydratation hyponatrémique avec coup de chaleur</span> ⭐ chez un nourrisson → évoquer la <span class=\"kw-etio\">mucoviscidose</span>.</li>\n  <li><span class=\"kw-alerte\">Hypotonie néonatale + dysmorphie faciale + pli palmaire transverse unique</span> → <span class=\"kw-etio\">trisomie 21</span> ; <strong>caryotype urgent</strong>.</li>\n  <li><span class=\"kw-alerte\">Garçon avec déficience intellectuelle + retard de langage majeur + grandes oreilles + visage allongé</span> → <strong>X fragile</strong> (<span class=\"kw-bio\">PCR FMR1</span>).</li>\n  <li><span class=\"kw-alerte\">Femme &lt; <span class=\"kw-chiffre\">40 ans</span> avec insuffisance ovarienne prématurée</span> → rechercher systématiquement une <strong>prémutation FMR1</strong> (<span class=\"kw-etio\">FXPOI</span>).</li>\n  <li><span class=\"kw-alerte\">Cardiopathie congénitale, atrésie duodénale, leucémie aiguë myéloblastique chez l'enfant</span> → toujours rechercher une <span class=\"kw-etio\">T21</span>.</li>\n  <li><span class=\"kw-alerte\">Risque T21 ≥ <span class=\"kw-chiffre\">1/50</span></span> au <span class=\"kw-def\">dépistage</span> combiné → <span class=\"kw-ttt\">caryotype fœtal</span> d'emblée ou <span class=\"kw-ttt\">NIPT</span> puis caryotype.</li>\n  <li><span class=\"kw-alerte\">Femme RhD-négatif</span> + prélèvement ovulatoire → <span class=\"kw-ttt\">Ig anti-D dans les <span class=\"kw-chiffre\">72 h</span></span>.</li>\n</ul>","principes":"\n<p><strong>Conseil <span class=\"kw-etio\">génétique</span> — règles de base :</strong></p>\n<ul>\n  <li><strong>Information loyale, claire, appropriée</strong>, sans pression, <strong>neutralité bienveillante</strong> du médecin.</li>\n  <li><span class=\"kw-def\">Consentement écrit</span> à chaque étape (<span class=\"kw-def\">dépistage</span> marqueurs, échographies, examens invasifs, examen <span class=\"kw-etio\">génétique</span>).</li>\n  <li><strong>Arbre généalogique sur <span class=\"kw-chiffre\">≥ 3 générations</span></strong> systématique.</li>\n  <li><strong>Information de la parentèle</strong> : devoir du patient si transmissible (loi de bioéthique 2011/2021) ; le médecin peut informer indirectement via le patient.</li>\n  <li>Examen <span class=\"kw-etio\">génétique</span> réalisé après <strong>consultation préalable spécialisée</strong> + délai de réflexion ; résultat rendu en consultation.</li>\n  <li><span class=\"kw-def\">DPN</span> / <span class=\"kw-def\">DPI</span> : encadrés par <strong>CPDPN</strong>, justifiés par une <strong>affection d'une particulière gravité reconnue incurable au moment du diagnostic</strong>.</li>\n</ul>\n<p><strong>Questions éthiques majeures :</strong></p>\n<ul>\n  <li>Eugénisme et dérive du <span class=\"kw-def\">dépistage</span> de <span class=\"kw-clinique\">masse</span> → encadrement légal strict.</li>\n  <li>Diagnostic présymptomatique de maladies sans traitement (<span class=\"kw-etio\">Huntington</span>, <span class=\"kw-etio\">FXTAS</span>) → <strong>protocole spécifique multidisciplinaire</strong>.</li>\n  <li>Information des apparentés <span class=\"kw-bio\">vs</span> secret médical.</li>\n  <li>Décision parentale d'<span class=\"kw-ttt\">IMG</span> : respect du choix sans jugement.</li>\n  <li>Diagnostic des mineurs : limité aux pathologies à expression pédiatrique avec PEC disponible.</li>\n</ul>","suivi":"\n<p><strong>Trisomie 21 — <span class=\"kw-def\">suivi</span> à vie :</strong></p>\n<ul>\n  <li>Bilan initial : <span class=\"kw-bio\">NFS + TSH + T4L</span> + <span class=\"kw-imagerie\">échographie cardiaque</span> + <span class=\"kw-imagerie\">échographie rénale</span>.</li>\n  <li><strong>Annuel</strong> : <span class=\"kw-clinique\">audition</span>, ophtalmologie (<span class=\"kw-clinique\">réfraction</span>, <span class=\"kw-clinique\">strabisme</span>, <span class=\"kw-etio\">cataracte</span>), <span class=\"kw-bio\">TSH</span>, <span class=\"kw-def\">dépistage</span> clinique <span class=\"kw-etio\">cœliaque</span>, dentaire.</li>\n  <li><strong><span class=\"kw-chiffre\">4 ans</span></strong> : <span class=\"kw-imagerie\">polysomnographie</span> (<span class=\"kw-etio\">SAOS</span> &gt; <span class=\"kw-chiffre\">50 %</span>).</li>\n  <li><strong>Adulte</strong> : <span class=\"kw-def\">dépistage</span> cancers (sein, col, côlon, testicule), <span class=\"kw-etio\">diabète</span>, <span class=\"kw-etio\">cataracte</span>, <span class=\"kw-etio\">hypothyroïdie</span> tous les <span class=\"kw-chiffre\">2–3 ans</span>.</li>\n  <li><span class=\"kw-ttt\">Rééducation psychomotricité</span> dès <span class=\"kw-chiffre\">3–6 mois</span> (CAMSP), <span class=\"kw-ttt\">orthophonie</span> dès <span class=\"kw-chiffre\">1 an</span>, obligatoire à <span class=\"kw-chiffre\">3 ans</span>.</li>\n</ul>\n<p><strong>Mucoviscidose :</strong></p>\n<ul>\n  <li>Consultation CRCM <strong>tous les <span class=\"kw-chiffre\">3 mois</span></strong> + bilan annuel (<span class=\"kw-imagerie\">RXT</span> + <span class=\"kw-bio\">EFR</span> + <span class=\"kw-bio\">ECBC</span>).</li>\n  <li><span class=\"kw-ttt\">Kiné respiratoire quotidienne</span> + aérosols (<span class=\"kw-ttt\">rhDNase</span>, <span class=\"kw-ttt\">sérum salé hypertonique</span>).</li>\n  <li><span class=\"kw-ttt\">Opothérapie pancréatique</span> + <span class=\"kw-ttt\">vitamines liposolubles (<strong>ADEK</strong>)</span> ⭐ systématiques.</li>\n  <li>Vaccinations : <span class=\"kw-ttt\">grippe annuelle</span>, <span class=\"kw-ttt\">hépatite A</span>, <span class=\"kw-ttt\">pneumocoque 23-valences</span> après <span class=\"kw-chiffre\">2 ans</span>.</li>\n  <li>PEC à <span class=\"kw-chiffre\">100 %</span> (<span class=\"kw-def\">ALD</span>), associations (<em>Vaincre la Mucoviscidose</em>).</li>\n</ul>\n<p><strong>X fragile :</strong></p>\n<ul>\n  <li><span class=\"kw-def\">Suivi</span> pluridisciplinaire (neuropédiatre, pédopsychiatre, généticien) + scolarité adaptée.</li>\n  <li>Femmes prémutées : <span class=\"kw-def\">surveillance</span> ovarienne (<span class=\"kw-etio\">FXPOI</span>) + thyroïdienne ; <span class=\"kw-ttt\">THS</span> jusqu'à âge ménopause si <span class=\"kw-etio\">IOP</span>.</li>\n  <li>Étude familiale en cascade (apparentés à proposer en consultation <span class=\"kw-etio\">génétique</span>).</li>\n</ul>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Dépistage prénatal T21 — calcul combiné du risque","detail":"Âge maternel + échographie T1 (clarté nuque) + marqueurs sériques (PAPP-A + β-hCG au T1). Consentement écrit à chaque étape.","branches":[{"to":"calc","label":"Résultat du risque","color":"blue"}]},{"id":"calc","kind":"decision","label":"Risque calculé","detail":"Trois zones de décision selon le seuil.","branches":[{"to":"faible","label":"< 1/1000","color":"green"},{"to":"inter","label":"1/1000 – 1/51","color":"amber"},{"to":"haut","label":"≥ 1/50","color":"red"}]},{"id":"faible","kind":"terminal","label":"Suivi habituel","color":"green","detail":"Aucun autre test, poursuite du suivi standard de la grossesse."},{"id":"inter","kind":"decision","label":"DPNI (NIPT) — ADN libre circulant","detail":"Test ADN T21 sur sang maternel (sensibilité &amp; spécificité &gt; 99 %). <strong>Ne remplace pas le caryotype.</strong>","branches":[{"to":"nipt-neg","label":"NIPT négatif","color":"green"},{"to":"carytope","label":"NIPT positif","color":"red"}]},{"id":"nipt-neg","kind":"terminal","label":"Suivi habituel","color":"green","detail":"Poursuite du suivi standard."},{"id":"haut","kind":"decision","label":"Choix du couple","detail":"Caryotype fœtal d'emblée OU NIPT en 1ʳᵉ intention.","branches":[{"to":"carytope","label":"Caryotype fœtal","color":"red"}]},{"id":"carytope","kind":"decision","label":"Prélèvement invasif","detail":"Choriocentèse dès 11 SA (FC 1 %) OU amniocentèse dès 15 SA (FC 0,5 %). Ig anti-D &lt; 72 h si RhD-.","branches":[{"to":"dx-pos","label":"Trisomie 21 confirmée","color":"red"},{"to":"dx-neg","label":"Caryotype normal","color":"green"}]},{"id":"dx-neg","kind":"terminal","label":"Grossesse poursuivie","color":"green","detail":"Suivi obstétrical standard. Information sur les limites du caryotype (microdélétions non vues)."},{"id":"dx-pos","kind":"terminal","label":"Consultation CPDPN + IMG possible","color":"red","detail":"Information du couple, accompagnement psychologique, <strong>IMG possible jusqu'au terme</strong> (choisie dans &gt; 95 % des cas), ou poursuite avec préparation à l'accueil + filière T21."}]},"objectifs":[{"id":"45-1","rang":"A","rubrique":"Définition","titre":"Connaître les règles de bases du conseil génétique","frequence":3,"contenu":"\n<p>Le <span class=\"kw-def\">conseil génétique</span> est une consultation médicale spécialisée délivrée par un <strong>généticien clinique</strong> (souvent avec un <span class=\"kw-def\">conseiller en génétique</span>), qui vise à informer un individu ou un couple sur le risque de survenue / récurrence d'une <span class=\"kw-def\">maladie génétique</span> et sur les options disponibles (<span class=\"kw-def\">DPN</span>, <span class=\"kw-def\">DPI</span>, <span class=\"kw-def\">dépistage en cascade</span>).</p>\n<table>\n  <thead><tr><th>Règle</th><th>Détail</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Information</strong></td><td>Loyale, claire, appropriée, <strong>non-directive</strong>, en <span class=\"kw-def\">neutralité bienveillante</span>.</td></tr>\n    <tr><td><strong>Consentement</strong></td><td><span class=\"kw-alerte\">Consentement écrit obligatoire</span> avant tout examen <span class=\"kw-etio\">génétique</span> (loi de bioéthique). Distinct pour <span class=\"kw-def\">dépistage</span> / <span class=\"kw-imagerie\">échographie</span> / examens invasifs.</td></tr>\n    <tr><td><strong>Arbre généalogique</strong></td><td>Systématique sur <span class=\"kw-chiffre\">≥ 3 générations</span>.</td></tr>\n    <tr><td><strong>Délai de réflexion</strong></td><td>Entre consultation et prélèvement <span class=\"kw-etio\">génétique</span>.</td></tr>\n    <tr><td><strong>Rendu du résultat</strong></td><td>En consultation, jamais par téléphone ni par courrier seul.</td></tr>\n    <tr><td><strong>Information de la parentèle</strong></td><td>Devoir du patient si maladie transmissible grave susceptible de mesures préventives ou curatives ; le médecin peut informer indirectement les apparentés via le patient.</td></tr>\n    <tr><td><strong>Examen du mineur</strong></td><td>Limité aux pathologies à expression pédiatrique pour lesquelles existe une PEC.</td></tr>\n    <tr><td><strong>Diagnostic présymptomatique</strong></td><td>(<span class=\"kw-etio\">Huntington</span>, <span class=\"kw-etio\">FXTAS</span>…) → <strong>protocole multidisciplinaire</strong> (généticien, psychologue, neurologue).</td></tr>\n  </tbody>\n</table>"},{"id":"45-2","rang":"B","rubrique":"Définition","titre":"Connaître le retentissement du diagnostic d'une maladie génétique dans une famille","frequence":4,"contenu":"\n<p>La révélation d'une <span class=\"kw-def\">maladie génétique</span> a un <strong>retentissement majeur</strong>, individuel et familial.</p>\n<table>\n  <thead><tr><th>Plan</th><th>Conséquences</th></tr></thead>\n  <tbody>\n    <tr><td>Psychologique parental</td><td>Sidération, déni, <span class=\"kw-clinique\">culpabilité</span>, <span class=\"kw-clinique\">dépression</span>, <span class=\"kw-clinique\">anxiété</span>, deuil de l'enfant « parfait ».</td></tr>\n    <tr><td>Conjugal</td><td>Tensions parentales, accusations réciproques, séparation/divorce.</td></tr>\n    <tr><td>Affectif vis-à-vis de l'enfant</td><td>Rejet (parfois abandon, maltraitance) <em>ou</em> surprotection au détriment de la fratrie.</td></tr>\n    <tr><td>Fratrie</td><td>Sentiment de mise à l'écart, culpabilité, parentification, anxiété sur sa propre descendance.</td></tr>\n    <tr><td>Apparentés</td><td>Inquiétude sur leur propre statut, démarche de <span class=\"kw-def\">dépistage en cascade</span>, retentissement reproductif.</td></tr>\n    <tr><td>Social</td><td>Stigmatisation, retentissement professionnel, organisation du quotidien.</td></tr>\n    <tr><td>Reproductif</td><td>Renoncement à un projet d'enfant, recours au <span class=\"kw-def\">DPN</span>/<span class=\"kw-def\">DPI</span>, <span class=\"kw-ttt\">IMG</span> ; deuil.</td></tr>\n  </tbody>\n</table>\n<p><strong>Accompagnement</strong> : <span class=\"kw-def\">annonce</span> en endroit calme, en présence des 2 parents si possible, information adaptée, éviter les affirmations péremptoires sur le <span class=\"kw-def\">pronostic</span>, revoir rapidement les parents, orienter vers les <strong>associations de patients</strong> et un <span class=\"kw-ttt\">soutien psychologique</span>.</p>"},{"id":"45-3","rang":"A","rubrique":"Définition","titre":"Connaître les questions éthiques en jeu dans le conseil génétique","frequence":0,"contenu":"\n<ul>\n  <li><strong>Eugénisme</strong> et risque de dérive du <span class=\"kw-def\">dépistage</span> de <span class=\"kw-clinique\">masse</span> (<span class=\"kw-etio\">T21</span> +++).</li>\n  <li><strong>Diagnostic présymptomatique</strong> de maladies sans traitement (<span class=\"kw-etio\">Huntington</span>, <span class=\"kw-etio\">FXTAS</span>) : protocole structuré multidisciplinaire, délai de réflexion long, <span class=\"kw-ttt\">accompagnement psychologique</span>.</li>\n  <li><strong>Conflit secret médical ↔ information des apparentés</strong> exposés à un risque <span class=\"kw-etio\">génétique</span> grave (encadré par la loi de bioéthique).</li>\n  <li><strong>Autonomie du patient</strong> : neutralité du médecin, <span class=\"kw-def\">non-directivité</span> du conseil.</li>\n  <li><strong>Décision d'<span class=\"kw-ttt\">IMG</span></strong> : respect du choix du couple, neutralité, tenir compte de la culture / philosophie / religion.</li>\n  <li><strong><span class=\"kw-def\">DPI</span></strong> : sélection embryonnaire, encadrement strict (couples à risque très élevé d'affection grave incurable).</li>\n  <li><strong>Examen <span class=\"kw-etio\">génétique</span> du mineur</strong> : limité aux pathologies à expression pédiatrique avec PEC disponible (préserver l'avenir de choix de l'enfant).</li>\n  <li><strong>Confidentialité</strong> des données génétiques (assurances, employeurs) : protection légale.</li>\n  <li><strong>Inégalité d'accès</strong> aux techniques (<span class=\"kw-bio\">NGS</span>, <span class=\"kw-def\">DPI</span>) sur le territoire.</li>\n</ul>"},{"id":"45-4","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de réalisation d'un caryotype fœtal","frequence":0,"contenu":"\n<p>Le <span class=\"kw-def\">caryotype fœtal</span> reste l'examen de référence pour le diagnostic de certitude d'une <span class=\"kw-def\">anomalie chromosomique</span>.</p>\n<table>\n  <thead><tr><th>Technique</th><th>Quand ?</th><th>Risque de fausse couche</th><th>Particularités</th></tr></thead>\n  <tbody>\n    <tr>\n      <td><strong>Choriocentèse / <span class=\"kw-ttt\">biopsie</span> de trophoblaste</strong></td>\n      <td>Dès <span class=\"kw-chiffre\">11 SA</span></td>\n      <td><span class=\"kw-chiffre\">1 %</span></td>\n      <td>Prélèvement transvaginal de tissu placentaire. Résultat &lt; <span class=\"kw-chiffre\">1 sem</span>. Risque de mosaïcisme placentaire.</td>\n    </tr>\n    <tr>\n      <td><strong>Amniocentèse</strong></td>\n      <td>Dès <span class=\"kw-chiffre\">15 SA</span></td>\n      <td><span class=\"kw-chiffre\">0,5 %</span></td>\n      <td><span class=\"kw-ttt\">Ponction</span> transabdominale écho-guidée de <span class=\"kw-chiffre\">10–20 mL</span> de LA. <strong>Méthode la plus utilisée</strong>. <span class=\"kw-bio\">FISH</span> <span class=\"kw-chiffre\">1–3 j</span>, culture <span class=\"kw-chiffre\">10–20 j</span>.</td>\n    </tr>\n    <tr>\n      <td><strong>Cordocentèse / <span class=\"kw-ttt\">ponction</span> de sang fœtal</strong></td>\n      <td>Dès <span class=\"kw-chiffre\">20 SA</span></td>\n      <td>Plus élevé</td>\n      <td>Centre spécialisé. Surtout à visée thérapeutique (<span class=\"kw-ttt\">transfusion in utero</span>).</td>\n    </tr>\n  </tbody>\n</table>\n<p><strong>Précautions :</strong></p>\n<ul>\n  <li><span class=\"kw-def\">Consentement écrit</span> signé.</li>\n  <li><span class=\"kw-ttt\">Ig anti-D &lt; <span class=\"kw-chiffre\">72 h</span></span> si femme <span class=\"kw-ttt\">RhD</span>-négatif et fœtus RhD+ ou inconnu.</li>\n  <li>Analyses : <span class=\"kw-bio\">caryotype</span>, <span class=\"kw-bio\">ADN fœtal (PCR)</span>, activités enzymatiques, <span class=\"kw-bio\">ACPA</span> (analyse chromosomique par puce à ADN).</li>\n</ul>"},{"id":"45-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du dépistage anténatal de trisomie 21","frequence":12,"contenu":"\n<p><span class=\"kw-def\">Dépistage</span> <strong>systématiquement proposé</strong> à toute femme enceinte (<span class=\"kw-def\">consentement écrit</span>). Repose sur le <span class=\"kw-def\">calcul combiné du risque</span> à 3 paramètres.</p>\n<table>\n  <thead><tr><th>Paramètre</th><th>Détail</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Âge maternel</strong></td><td>Seul FR connu pour la <span class=\"kw-etio\">T21</span>. Ne suffit plus seul pour indiquer un caryotype.</td></tr>\n    <tr>\n      <td><strong><span class=\"kw-imagerie\">Échographie</span></strong> (par échographiste agréé)</td>\n      <td>\n        <ul>\n          <li><strong>T1 (<span class=\"kw-chiffre\">11 SA – 13 SA + 6 j</span>)</strong> : <span class=\"kw-imagerie\">clarté nucale</span> <span class=\"kw-chiffre\">&lt; 3 mm</span>, recherche <span class=\"kw-imagerie\">hygroma colli</span>.</li>\n          <li><strong>T2 (<span class=\"kw-chiffre\">22 SA</span>)</strong> : signes malformatifs (<span class=\"kw-etio\">CAV</span>, <span class=\"kw-imagerie\">hypoplasie OPN</span>, <span class=\"kw-imagerie\">fémur court</span>…).</li>\n          <li><strong>T3 (<span class=\"kw-chiffre\">32 SA</span>)</strong> : <span class=\"kw-etio\">RCIU</span> tardif, <span class=\"kw-etio\">cardiopathie</span>.</li>\n        </ul>\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Marqueurs sériques maternels</strong></td>\n      <td>\n        <ul>\n          <li>T1 : <span class=\"kw-bio\">PAPP-A</span> + <span class=\"kw-bio\">β-hCG libre</span>.</li>\n          <li>T2 (si T1 non fait) : <span class=\"kw-bio\">AFP</span> + <span class=\"kw-bio\">β-hCG (ou hCG totales)</span> ± <span class=\"kw-bio\">œstriol non conjugué</span>.</li>\n        </ul>\n      </td>\n    </tr>\n  </tbody>\n</table>\n<p><strong>CAT selon le risque combiné :</strong></p>\n<table>\n  <thead><tr><th>Risque</th><th>Conduite</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-chiffre\">&lt; 1/1000</span></td><td><span class=\"kw-def\">Suivi</span> habituel.</td></tr>\n    <tr><td><span class=\"kw-chiffre\">1/1000 – 1/51</span></td><td><strong><span class=\"kw-ttt\">NIPT</span></strong> (ADN libre circulant) → si anormal : <span class=\"kw-ttt\">caryotype fœtal</span>.</td></tr>\n    <tr><td><span class=\"kw-chiffre\">≥ 1/50</span></td><td><span class=\"kw-ttt\">Caryotype fœtal</span> d'emblée <em>ou</em> <span class=\"kw-ttt\">NIPT</span> en 1ʳᵉ intention si la femme le souhaite.</td></tr>\n  </tbody>\n</table>\n<p><strong>Règles indispensables :</strong> écho T1 par échographiste <strong>agréé</strong> (sinon marqueurs T1 non interprétables) ; patiente vue au laboratoire <strong>avant <span class=\"kw-chiffre\">14 SA</span></strong> pour marqueurs T1. Sinon → marqueurs T2 non combinés.</p>"},{"id":"45-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic anténatal de trisomie 21","frequence":3,"contenu":"\n<p>Le <span class=\"kw-def\">DPN</span> repose sur un <strong>prélèvement invasif</strong> avec <span class=\"kw-bio\">caryotype fœtal</span> (seul examen de certitude).</p>\n<table>\n  <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n  <tbody>\n    <tr><td>Indications</td><td>\n      <ul>\n        <li>Risque combiné <span class=\"kw-chiffre\">≥ 1/50</span> ou risque <span class=\"kw-chiffre\">1/1000–1/51</span> avec <strong><span class=\"kw-bio\">NIPT</span> anormal</strong>.</li>\n        <li>Signes d'appel échographiques (<span class=\"kw-etio\">CAV</span>, <span class=\"kw-etio\">atrésie duodénale</span>, <span class=\"kw-imagerie\">hypoplasie OPN</span>…).</li>\n        <li>Remaniement chromosomique parental connu.</li>\n        <li>ATCD de fœtus / enfant avec <span class=\"kw-def\">anomalie chromosomique</span>.</li>\n      </ul>\n      <p><span class=\"kw-alerte\">L'âge maternel seul n'est plus une indication suffisante.</span></p>\n    </td></tr>\n    <tr><td>Prélèvements</td><td><span class=\"kw-ttt\">Choriocentèse</span> dès <span class=\"kw-chiffre\">11 SA</span> · <span class=\"kw-ttt\">Amniocentèse</span> dès <span class=\"kw-chiffre\">15 SA</span> · <span class=\"kw-ttt\">Cordocentèse</span> dès <span class=\"kw-chiffre\">20 SA</span>.</td></tr>\n    <tr><td>Analyses</td><td><span class=\"kw-bio\">Caryotype</span> ± <span class=\"kw-bio\">FISH</span> interphasique (rapide, ciblée chromosome 21) ± <span class=\"kw-bio\">ACPA</span>.</td></tr>\n    <tr><td>Précaution</td><td><span class=\"kw-ttt\">Ig anti-D</span> &lt; <span class=\"kw-chiffre\">72 h</span> si femme <span class=\"kw-ttt\">RhD</span>-négatif.</td></tr>\n    <tr><td>Si positif</td><td><strong><span class=\"kw-ttt\">IMG</span> possible jusqu'au terme</strong> (choisie dans <span class=\"kw-chiffre\">&gt; 95 %</span> des cas).</td></tr>\n  </tbody>\n</table>\n<p><strong>NIPT (ADN libre circulant)</strong> : analyse de l'ADN fœtal présent dans le plasma maternel dès la <span class=\"kw-chiffre\">7ᵉ semaine</span> (Se &amp; Sp &gt; <span class=\"kw-chiffre\">99 %</span> pour la <span class=\"kw-etio\">T21</span>). <span class=\"kw-alerte\">Ne remplace pas le caryotype</span> pour le diagnostic.</p>"},{"id":"45-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du conseil génétique en cas d'antécédent de trisomie 21","frequence":1,"contenu":"\n<p>Le conseil dépend du <strong>type cytogénétique</strong> de la <span class=\"kw-etio\">T21</span> de l'enfant index : <strong>caryotype des parents obligatoire</strong> si <span class=\"kw-def\">translocation</span>.</p>\n<table>\n  <thead><tr><th>Forme</th><th>Mécanisme</th><th>Caryotype parental</th><th>Récurrence</th></tr></thead>\n  <tbody>\n    <tr><td><strong>T<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>21</span> l</span>ibre</strong> (≈ <span class=\"kw-chiffre\">95 %</span>)</td><td><span class=\"kw-def\">Non-disjonction méiotique</span> accidentelle (souvent maternelle)</td><td><span class=\"kw-alerte\">Inutile</span> ❌</td><td><span class=\"kw-chiffre\">≈ 1 %</span> (mosaïques germinales)</td></tr>\n    <tr><td><strong>T21 par translocation robertsonienne</strong> (≈ <span class=\"kw-chiffre\">3 %</span>)</td><td>46 chr + chr recombinant ; <strong><span class=\"kw-chiffre\">50 %</span> héritées</strong> d'un parent porteur d'une <span class=\"kw-def\">translocation équilibrée</span> impliquant un acrocentrique (13, 14, 15, 21, 22)</td><td><span class=\"kw-alerte\">Indispensable</span> ✅</td><td>\n      <ul>\n        <li>Parents normaux : <span class=\"kw-chiffre\">1 %</span></li>\n        <li>Mère porteuse t(14;21) : <span class=\"kw-chiffre\">10–15 %</span></li>\n        <li>Père porteur t(14;21) : <span class=\"kw-chiffre\">2–5 %</span></li>\n        <li>Translocation t(21;21) : <span class=\"kw-chiffre\">100 %</span></li>\n      </ul>\n    </td></tr>\n    <tr><td><strong>T21 par translocation réciproque</strong></td><td>Rare ; ≈ <span class=\"kw-chiffre\">50 %</span> héritées</td><td>Indispensable ✅</td><td><span class=\"kw-chiffre\">10–100 %</span> selon parent porteur</td></tr>\n  </tbody>\n</table>\n<p><strong>Risque selon l'âge maternel</strong> (T<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>21</span> l</span>ibre, en l'absence d'ATCD) :</p>\n<ul>\n  <li><span class=\"kw-chiffre\">20 ans</span> → <span class=\"kw-chiffre\">1/1500</span></li>\n  <li><span class=\"kw-chiffre\">35 ans</span> → <span class=\"kw-chiffre\">1/350</span></li>\n  <li><span class=\"kw-chiffre\">40 ans</span> → <span class=\"kw-chiffre\">1/100</span></li>\n  <li><span class=\"kw-chiffre\">45 ans</span> → <span class=\"kw-chiffre\">1/30</span></li>\n  <li>Femme T21 elle-même → <span class=\"kw-chiffre\">1/3</span></li>\n</ul>\n<p><strong>Si un parent porte une translocation équilibrée :</strong> <span class=\"kw-alerte\">les apparentés au 1ᵉʳ degré doivent être informés</span> et se voir proposer un <span class=\"kw-bio\">caryotype</span>.</p>"},{"id":"45-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités de prescription d'un caryotype","frequence":0,"contenu":"\n<p>La prescription d'un <span class=\"kw-def\">caryotype</span> (constitutionnel) doit respecter le cadre légal des examens génétiques.</p>\n<table>\n  <thead><tr><th>Étape</th><th>Détail</th></tr></thead>\n  <tbody>\n    <tr><td>Consultation préalable</td><td>Spécialisée (généticien ou prescripteur formé), information loyale.</td></tr>\n    <tr><td>Consentement</td><td><span class=\"kw-alerte\">Écrit, signé, daté</span>, conservé dans le dossier. Pour le mineur : signature des 2 titulaires de l'autorité parentale.</td></tr>\n    <tr><td>Prélèvement</td><td>Sang sur tube <strong>hépariné</strong> (<span class=\"kw-bio\">lymphocytes</span> T → culture stimulée par PHA).</td></tr>\n    <tr><td>Délai</td><td><span class=\"kw-chiffre\">2–3 semaines</span> (culture cellulaire + bandes G).</td></tr>\n    <tr><td>Rendu</td><td>En consultation. Si anomalie : <span class=\"kw-def\">conseil génétique</span> familial.</td></tr>\n  </tbody>\n</table>\n<p><strong>Indications classiques d'un caryotype constitutionnel :</strong></p>\n<ul>\n  <li><span class=\"kw-clinique\">Dysmorphie</span> + <span class=\"kw-def\">déficience intellectuelle</span>.</li>\n  <li><span class=\"kw-etio\">Malformations congénitales</span> multiples.</li>\n  <li><span class=\"kw-clinique\">Retard de croissance</span> inexpliqué (<span class=\"kw-etio\">Turner</span> chez la fille).</li>\n  <li>Anomalies de la <span class=\"kw-def\">différenciation sexuelle</span>.</li>\n  <li><span class=\"kw-clinique\">Aménorrhée primaire</span>, <span class=\"kw-clinique\">infertilité</span>, <span class=\"kw-clinique\">fausses couches à répétition</span>.</li>\n  <li>Bilan familial après diagnostic d'une <span class=\"kw-def\">anomalie chromosomique</span> chez un apparenté.</li>\n</ul>\n<p><strong><span class=\"kw-bio\">ACPA</span></strong> (analyse chromosomique par puce à ADN) : meilleure résolution, désormais examen de 1ʳᵉ intention dans la <span class=\"kw-def\">déficience intellectuelle</span> inexpliquée (détecte <span class=\"kw-def\">microdélétions / microduplications</span> &lt; <span class=\"kw-chiffre\">5 Mb</span> invisibles au caryotype).</p>"},{"id":"45-9","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître l'évolution de la trisomie 21","frequence":3,"contenu":"\n<p>Espérance de vie aujourd'hui <span class=\"kw-chiffre\">&gt; 50 ans</span> grâce aux progrès de la PEC (<span class=\"kw-ttt\">chirurgie des CAV</span>, <span class=\"kw-ttt\">ATB</span>, <span class=\"kw-def\">suivi</span> multidisciplinaire).</p>\n<table>\n  <thead><tr><th>Domaine</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n  <tbody>\n    <tr><td>Cognitif</td><td><span class=\"kw-def\">Déficience intellectuelle</span> <strong>variable</strong> (QI moyen ≈ <span class=\"kw-chiffre\">45</span>, plage <span class=\"kw-chiffre\">25–80</span>). <strong>1ʳᵉ cause <span class=\"kw-etio\">génétique</span> de déficience intellectuelle</strong>. Lecture/écriture possibles pour <span class=\"kw-chiffre\">2/3</span>.</td></tr>\n    <tr><td>Langage</td><td><span class=\"kw-alerte\">Retard de langage marqué</span> ⭐.</td></tr>\n    <tr><td>Cardiaque</td><td><span class=\"kw-etio\">CAV</span> (<span class=\"kw-chiffre\">50 %</span> des cardiopathies T21), <span class=\"kw-etio\">tétralogie de Fallot</span>, <span class=\"kw-etio\">CIV</span>, <span class=\"kw-etio\">CIA</span>.</td></tr>\n    <tr><td>Digestif</td><td><span class=\"kw-etio\">Atrésie duodénale</span> (<span class=\"kw-chiffre\">10 %</span>), <span class=\"kw-etio\">imperforation anale</span>, <span class=\"kw-etio\">Hirschsprung</span> (<span class=\"kw-chiffre\">1 %</span>), <span class=\"kw-etio\">maladie cœliaque</span> (<span class=\"kw-chiffre\">5 %</span>).</td></tr>\n    <tr><td>Endocrinien</td><td><span class=\"kw-alerte\"><span class=\"kw-etio\">Hypothyroïdie</span> / <span class=\"kw-etio\">thyroïdite</span></span> <span class=\"kw-chiffre\">4–18 %</span> (<span class=\"kw-def\">dépistage</span> <strong>annuel</strong>). <span class=\"kw-etio\">DT1</span> (<span class=\"kw-chiffre\">1 %</span>), <span class=\"kw-etio\">DT2</span> (lié à l'<span class=\"kw-etio\">obésité</span>, dépistage adulte). <strong><span class=\"kw-etio\">Obésité</span> <span class=\"kw-chiffre\">30–50 %</span></strong>.</td></tr>\n    <tr><td>Respiratoire / sommeil</td><td><span class=\"kw-alerte\"><span class=\"kw-etio\">SAOS</span> &gt; <span class=\"kw-chiffre\">50 %</span></span> ⭐ → <strong><span class=\"kw-imagerie\">polysomnographie</span> systématique à <span class=\"kw-chiffre\">4 ans</span></strong>.</td></tr>\n    <tr><td>ORL / Ophtalmo</td><td>Infections ORL récidivantes (<span class=\"kw-chiffre\">60 %</span>), <span class=\"kw-clinique\">surdité</span> (<span class=\"kw-chiffre\">45–75 %</span>, <span class=\"kw-def\">dépistage</span> annuel), <span class=\"kw-clinique\">strabisme</span>/<span class=\"kw-clinique\">myopie</span> (<span class=\"kw-chiffre\">60 %</span>), <span class=\"kw-alerte\"><span class=\"kw-etio\">cataracte</span> (<span class=\"kw-chiffre\">15 %</span>) ⭐</span> (examen annuel puis tous les <span class=\"kw-chiffre\">3 ans</span> à l'adulte).</td></tr>\n    <tr><td>Hématologique</td><td><span class=\"kw-clinique\">Hyperleucocytose néonatale</span>, <span class=\"kw-etio\">LAM</span> (<span class=\"kw-chiffre\">1 %</span>, ×<span class=\"kw-chiffre\">10</span> <span class=\"kw-bio\">vs</span> pop générale).</td></tr>\n    <tr><td>Neurologique</td><td><span class=\"kw-etio\">Maladie d'Alzheimer</span> <span class=\"kw-chiffre\">50 %</span> après <span class=\"kw-chiffre\">40 ans</span>. <span class=\"kw-etio\">Épilepsie</span> (<span class=\"kw-chiffre\">1–10 %</span>, <span class=\"kw-etio\">syndrome de West</span>).</td></tr>\n    <tr><td>Os / Postural</td><td><span class=\"kw-alerte\">Instabilité C1/C2</span> (<strong>prudence <span class=\"kw-ttt\">intubation</span></strong>), <span class=\"kw-clinique\">pieds plats valgus</span>, <span class=\"kw-etio\">ostéoporose</span> adulte.</td></tr>\n    <tr><td>Fertilité</td><td>Femmes : fertilité normale (transmission <span class=\"kw-chiffre\">1/3</span>). Hommes : <span class=\"kw-alerte\">stérilité (<span class=\"kw-chiffre\">98 %</span>)</span>.</td></tr>\n    <tr><td>Vieillissement</td><td><strong>Précoce de <span class=\"kw-chiffre\">30 ans</span></strong> : <span class=\"kw-etio\">cataracte sénile</span>, <span class=\"kw-etio\">arthrose</span>, <span class=\"kw-clinique\">fatigabilité</span>.</td></tr>\n  </tbody>\n</table>"},{"id":"45-10","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","frequence":3,"contenu":"\n<p><strong>Aucun signe pathognomonique.</strong> La seule manifestation quasi-constante est l'<span class=\"kw-alerte\"><span class=\"kw-clinique\">hypotonie marquée</span></span>, non spécifique. Triade phénotypique de toute anomalie chromosomique (inconstante) : <span class=\"kw-clinique\">retard psychomoteur</span> + <span class=\"kw-clinique\">dysmorphie</span> + <span class=\"kw-etio\">malformation</span>.</p>\n<table>\n  <tbody>\n    <tr>\n      <td>Crâne<br>Visage</td>\n      <td><ul>\n        <li><span class=\"kw-clinique\">Occiput plat</span>, petit périmètre crânien (autour de <span class=\"kw-chiffre\">− 2 DS</span>)</li>\n        <li><span class=\"kw-clinique\">Nuque courte et large</span> (avec un excès de peau en période néonatale)</li>\n        <li>Visage rond et plat</li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td>Yeux</td>\n      <td><ul>\n        <li><span class=\"kw-clinique\">Hypertélorisme</span> (distance excessive entre les orbites)</li>\n        <li><span class=\"kw-clinique\">Fentes palpébrales obliques en haut et en dehors</span></li>\n        <li><span class=\"kw-clinique\">Épicanthus</span> (insertion de la paupière supérieure formant un repli recouvrant le canthus interne)</li>\n        <li><span class=\"kw-clinique\">Taches de Brushfield</span> sur l'iris</li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td>Oreille</td>\n      <td><span class=\"kw-clinique\">Petites oreilles rondes</span> mal ourlées</td>\n    </tr>\n    <tr>\n      <td>Nez</td>\n      <td><span class=\"kw-clinique\">Nez court</span> par hypoplasie des os propres du nez, avec <span class=\"kw-clinique\">ensellure nasale plate</span> (contribuant à l'épicanthus) → petits nez en boule</td>\n    </tr>\n    <tr>\n      <td>Bouche</td>\n      <td><ul>\n        <li><span class=\"kw-clinique\">Petite bouche</span>, souvent tenue ouverte (du fait de l'hypotonie faciale)</li>\n        <li><span class=\"kw-clinique\">Langue protruse</span> donnant une impression de macroglossie, avec langue plicaturée</li>\n        <li><span class=\"kw-clinique\">Mâchoire inférieure devenant prognathe</span> avec l'âge</li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td>Taille</td>\n      <td><span class=\"kw-alerte\">Retard statural</span> (autour de <span class=\"kw-chiffre\">− 2 DS</span>)</td>\n    </tr>\n    <tr>\n      <td>Peau</td>\n      <td>Peau <span class=\"kw-clinique\">sèche</span> ⭐, hyperlaxité articulaire et cutané, <span class=\"kw-clinique\">livedo</span></td>\n    </tr>\n    <tr>\n      <td>Mains</td>\n      <td><ul>\n        <li>Mains trapues, avec des doigts courts et <span class=\"kw-clinique\">hyperlaxes</span></li>\n        <li><span class=\"kw-clinique\">Clinodactylie du 5ᵉ doigt</span> (déviation latérale liée à une brachymésophalangie : phalange de P2 courte)</li>\n        <li><span class=\"kw-alerte\">Pli palmaire transverse unique</span> (concerne 2/3 des mains de trisomiques, et 1 % en population générale)</li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td>Pieds</td>\n      <td><ul>\n        <li><span class=\"kw-clinique\">Pieds larges et courts</span>, avec <span class=\"kw-alerte\">signe de la sandale</span> (espace marqué entre le hallux et le 2ᵉ orteil)</li>\n        <li>Plantes des pieds plissées</li>\n      </ul></td>\n    </tr>\n  </tbody>\n</table>\n<p>À la suspicion → <strong><span class=\"kw-bio\">caryotype standard</span></strong> (confirmation) ± <span class=\"kw-bio\">FISH 21</span> si réponse rapide nécessaire.</p>"},{"id":"45-11","rang":"B","rubrique":"Prise en charge","titre":"Connaître l'évolution naturelle d'une personne atteinte de trisomie 21 tout au long de sa vie","frequence":1,"contenu":"\n<table>\n  <tbody>\n    <tr>\n      <td></td>\n      <th style=\"text-align:left\">Suivi de la trisomie 21 chez l'enfant 👶</th>\n    </tr>\n    <tr>\n      <td><strong>Bilan diagnostique</strong></td>\n      <td>\n        <p>Bilan diagnostic réalisé au moment du diagnostic de trisomie 21 :</p>\n        <p>→ <span class=\"kw-bio\">NFS</span> + <span class=\"kw-bio\">Bilan thyroïdien</span> + <span class=\"kw-imagerie\">Échographie cardiaque</span> + <span class=\"kw-imagerie\">Échographie rénale</span></p>\n      </td>\n    </tr>\n    <tr>\n      <td><strong>Surveillance<br/>Dépistage</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li><span class=\"kw-etio\">Surdité</span> : dès la <span class=\"kw-chiffre\">1ère année</span>, puis dépistage <span class=\"kw-chiffre\">annuel</span></li>\n        <li><span class=\"kw-clinique\">Examen ophtalmologique</span> : régulier, indispensable (réfraction, strabisme, cataracte)</li>\n        <li><span class=\"kw-etio\">Dysthyroïdies</span> : doivent être recherchées <span class=\"kw-chiffre\">annuellement</span></li>\n        <li><span class=\"kw-etio\">Maladie cœliaque</span> : doit rester à l'esprit (dépistage <span class=\"kw-clinique\">clinique</span>)</li>\n        <li><span class=\"kw-etio\">SAOS</span> : dépisté par <span class=\"kw-imagerie\">polysomnographie</span> est recommandé à <span class=\"kw-chiffre\">4 ans</span></li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td><strong>Rééducation</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li><span class=\"kw-ttt\">Rééducation en psychomotricité</span> :\n          <ul style=\"margin:0; padding-left:18px; list-style:none\">\n            <li>→ À partir de quel âge ? peut être prescrite <span class=\"kw-chiffre\">dès l'âge de 3 à 6 mois</span></li>\n            <li>→ Orientation : <strong>CAMSP</strong> (jusqu'à l'âge de 6 ans), <strong>SESSAD</strong>, ou par un <strong>praticien libéral formé</strong></li>\n          </ul>\n        </li>\n        <li><span class=\"kw-ttt\">Rééducation orthophonique</span> :\n          <ul style=\"margin:0; padding-left:18px; list-style:none\">\n            <li>→ Possible à partir de quand ? peut être ajoutée <span class=\"kw-chiffre\">dès l'âge de 1 an</span></li>\n            <li>→ Nécessaire à quel âge ? doit être instaurée à <span class=\"kw-chiffre\">3 ans</span></li>\n          </ul>\n        </li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td><strong>Scolarité</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li>Suivi par un <span class=\"kw-ttt\">psychologue</span> : peut être utile, surtout après l'entrée en CP et à la puberté</li>\n        <li><strong>Scolarité adaptée au niveau intellectuel</strong> : enseignement habituel avec une auxiliaire de vie scolaire (<strong>AVS</strong>), <strong>ULIS</strong> ou <strong>IME</strong></li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td></td>\n      <th style=\"text-align:left\">Suivi de la trisomie 21 chez l'adulte 🧔</th>\n    </tr>\n    <tr>\n      <td><strong>Pathologies<br/>à dépister</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li><span class=\"kw-etio\">Côlon</span>, <span class=\"kw-etio\">Sein</span>, <span class=\"kw-etio\">Col de l'utérus</span>, <span class=\"kw-etio\">Cancer du testicule</span></li>\n        <li><span class=\"kw-etio\">Hypothyroïdie</span>, <span class=\"kw-etio\">Diabète</span>, <span class=\"kw-etio\">Maladie cœliaque</span>, <span class=\"kw-etio\">Cataracte</span> : à dépister tous les <span class=\"kw-chiffre\">2 ou 3 ans</span></li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td><strong>Vie professionnelle</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li><span class=\"kw-ttt\">Entretien des acquis après la période scolaire</span> : pour maintenir le niveau d'autonomie et d'intégration sociale atteint</li>\n        <li><strong>RQTH</strong> ou Travail dans des structures adaptées (<strong>ESAT</strong>)</li>\n      </ul></td>\n    </tr>\n    <tr>\n      <td><strong>Vie sexuelle</strong></td>\n      <td><ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n        <li><span class=\"kw-clinique\">Capacité de mener une vie affective normale et peuvent être sexuellement actifs</span> : pour la majorité des patients</li>\n        <li><span class=\"kw-medic\">Contraception</span> adaptée doit être discutée pour les adolescentes et femmes trisomiques</li>\n      </ul></td>\n    </tr>\n  </tbody>\n</table>"},{"id":"45-12","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic anténatal de la mucoviscidose","frequence":3,"contenu":"\n<p>Le <span class=\"kw-def\">DPN</span> de la <span class=\"kw-etio\">mucoviscidose</span> est proposé aux <strong>couples à risque connu</strong> ou devant des signes d'appel échographiques.</p>\n<table>\n  <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n  <tbody>\n    <tr><td>Couple ayant déjà eu un enfant atteint</td><td>Les 2 parents sont <span class=\"kw-def\">hétérozygotes</span> (risque <span class=\"kw-chiffre\">1/4</span>) → <span class=\"kw-def\">DPN</span> systématiquement proposé.</td></tr>\n    <tr><td>Hétérozygotie connue chez 1 parent</td><td>Recherche d'une <span class=\"kw-bio\">mutation fréquente</span> chez l'autre parent.</td></tr>\n    <tr><td>Apparentés proches d'un enfant atteint</td><td>Recherche d'<span class=\"kw-def\">hétérozygotie</span> chez les 2 parents.</td></tr>\n    <tr><td>Signes échographiques évocateurs</td><td><span class=\"kw-imagerie\">Dilatation digestive</span>, <strong><span class=\"kw-imagerie\">hyperéchogénicité intestinale</span></strong>, <span class=\"kw-imagerie\">non-visualisation de la vésicule biliaire</span>, <span class=\"kw-etio\">péritonite méconiale</span>.</td></tr>\n  </tbody>\n</table>\n<p><strong>Prélèvements :</strong> <span class=\"kw-ttt\">choriocentèse</span> dès <span class=\"kw-chiffre\">11 SA</span> (FC <span class=\"kw-chiffre\">1 %</span>) ou <span class=\"kw-ttt\">amniocentèse</span> dès <span class=\"kw-chiffre\">15 SA</span> (FC <span class=\"kw-chiffre\">0,5 %</span>).</p>\n<p><strong>Analyses :</strong></p>\n<ul>\n  <li><strong>Mutations parentales connues</strong> → recherche directe sur <span class=\"kw-bio\">ADN fœtal</span>, <span class=\"kw-chiffre\">Sp 100 %</span>.</li>\n  <li><strong>Mutations parentales inconnues</strong> (ex. ATCD d'enfant malade) → <strong>diagnostic indirect</strong> par <span class=\"kw-bio\">marqueurs polymorphes intra/extragéniques</span> + dosages <strong>biochimiques sur LA</strong> (<span class=\"kw-bio\">immunoenzymes intestinales, leucine aminopeptidase, PAL, γGT</span>) — <span class=\"kw-alerte\">nécessite une amniocentèse, pas une choriocentèse</span>.</li>\n</ul>\n<p><strong>Alternative</strong> : <span class=\"kw-def\">DPI</span> (diagnostic préimplantatoire) après <span class=\"kw-ttt\">ICSI</span>, sélection d'embryons indemnes.</p>"},{"id":"45-13","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du dépistage néonatal généralisé de la mucoviscidose","frequence":2,"contenu":"\n<p>Manifestations possibles dès la naissance (à connaître même hors Guthrie) : <span class=\"kw-etio\">iléus méconial</span>, <span class=\"kw-etio\">ictère cholestatique rétentionnel</span></p>\n<table>\n  <tbody>\n    <tr>\n      <td><strong>Enjeu</strong></td>\n      <td><span class=\"kw-def\">Dépistage</span> permet une prise en charge précoce des manifestations pulmonaires et digestives de la <span class=\"kw-etio\">mucoviscidose</span> (semblant ralentir l'évolution de la maladie et améliorer son pronostic en termes de survie)</td>\n    </tr>\n    <tr>\n      <td><strong>Indication</strong></td>\n      <td><span class=\"kw-def\">Dépistage systématique</span> autour de <span class=\"kw-chiffre\">72h</span> de vie</td>\n    </tr>\n    <tr>\n      <td><strong>Consentement ?</strong></td>\n      <td>Recueil du <span class=\"kw-def\">consentement signé</span> des parents (pour la recherche génétique éventuelle)</td>\n    </tr>\n    <tr>\n      <td><strong>Prélèvement</strong></td>\n      <td>Prélèvement d'une tache de sang au talon du nouveau-né, déposé sur papier buvard</td>\n    </tr>\n    <tr>\n      <td><strong>Dosage ?</strong></td>\n      <td>\n        <strong>Dosage sanguin de trypsine immunoréactive</strong> (TIR, enzyme pancréatique reflète la souffrance pancréatique <span class=\"kw-alerte\">si élevée</span>)\n        <ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n          <li><span class=\"kw-bio\">Sensibilité : assez sensible</span> (taux de FN entre <span class=\"kw-chiffre\">3–3,5%</span>)</li>\n          <li><span class=\"kw-alerte\">Spécificité : faible</span> (<span class=\"kw-chiffre\">4/5</span> enfants convoqués au CRCM suite à un dépistage positif n'ont pas la mucoviscidose)</li>\n        </ul>\n      </td>\n    </tr>\n    <tr>\n      <td><strong>CAT si anormal ?</strong></td>\n      <td>\n        <strong>Diagnostic moléculaire</strong> à la recherche des <span class=\"kw-chiffre\">29</span> mutations du gène <span class=\"kw-def\">CFTR</span> les plus fréquentes en France :\n        <ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n          <li>Si <span class=\"kw-bio\">absence de mutation</span> : nouveau <span class=\"kw-alerte\">dosage de TIR à 3 semaines</span> → convoqué au CRCM si élevée</li>\n          <li>Si <span class=\"kw-alerte\">mutation identifiée sur ≥ 1 allèle</span> : convocation au CRCM régional pour un test de la sueur</li>\n        </ul>\n      </td>\n    </tr>\n    <tr>\n      <td><strong>CRCM</strong></td>\n      <td>Centre de ressources et de compétences pour la mucoviscidose</td>\n    </tr>\n    <tr>\n      <td><strong>Note</strong></td>\n      <td>\n        Manifestations de mucoviscidose sont aussi possibles dès la naissance :\n        <ul style=\"margin:0; padding-left:0; list-style-position:inside; list-style-type:'- '\">\n          <li>Ictère cholestatique rétentionnel</li>\n          <li>Iléus méconial = occlusion iléon par méconium visqueux/sec (justifie lavage, ± chirurgie si échec)</li>\n        </ul>\n      </td>\n    </tr>\n  </tbody>\n</table>\n"},{"id":"45-14","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","frequence":2,"contenu":"\n<table>\n  <tbody>\n    <tr><td></td><td><strong>Test de la sueur</strong> = examen de confirmation diagnostique de référence</td></tr>\n    <tr><td>Rationnel</td><td>Anomalie de <span class=\"kw-def\">CFTR</span> se traduit au niveau de la <strong>glande sudoripare</strong> par un <strong>syndrome de perte de sel</strong></td></tr>\n    <tr><td>Normal</td><td>Teneur normale de chlorure dans la sueur : <span class=\"kw-bio\">&lt; <span class=\"kw-chiffre\">30 mmol/L</span> de chlorure</span></td></tr>\n    <tr><td>Pathologique</td><td>Teneur pathologique de chlorure dans la sueur : <span class=\"kw-alerte\">&gt; <span class=\"kw-chiffre\">60 mmol/L</span></span><br/>(diagnostic de mucoviscidose est affirmé après <span class=\"kw-alerte\"><span class=\"kw-chiffre\">2</span> examens positifs</span>)</td></tr>\n    <tr><td>Intermédiaire</td><td>\n      Si valeurs intermédiaires (<span class=\"kw-chiffre\">30–59 mmol/L</span>), il faut :\n      <ul>\n        <li><span class=\"kw-bio\">Répéter ultérieurement le test</span></li>\n        <li><span class=\"kw-bio\">Examens de biologie moléculaire</span> : peuvent aider</li>\n        <li><span class=\"kw-bio\">Mesures électrophysiologiques du transport des ions chlorures</span> en centre spécialisé : peuvent aider</li>\n      </ul>\n    </td></tr>\n    <tr><td></td><td><strong>Biologie moléculaire</strong> = complément nécessaire du test de la sueur</td></tr>\n    <tr><td>Principe</td><td>\n      Mise en évidence d'une mutation pathogène sur chaque allèle pour confirmer la mucoviscidose :\n      <ul>\n        <li>1. Recherche tout d'abord <span class=\"kw-bio\">les mutations les plus fréquentes</span></li>\n        <li>2. Étude <strong>plus extensive</strong> si besoin</li>\n      </ul>\n    </td></tr>\n    <tr><td>Résultat</td><td>\n      <ul>\n        <li>Soit patient <span class=\"kw-clinique\">homozygote pour la même mutation</span></li>\n        <li>Soit patient <span class=\"kw-clinique\">hétérozygote composite</span> (porteur de 2 mutations différentes)</li>\n      </ul>\n    </td></tr>\n  </tbody>\n</table>"},{"id":"45-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les manifestations de la mucoviscidose","frequence":3,"contenu":"\n<p>Maladie multisystémique. <strong>Manifestations respiratoires = <span class=\"kw-chiffre\">90 %</span> de la <span class=\"kw-def\">morbidité</span>.</strong></p>\n<table>\n  <thead><tr><th>Appareil</th><th>Manifestations</th></tr></thead>\n  <tbody>\n    <tr><td>🚩 Signe d'alerte ⭐</td><td><span class=\"kw-alerte\"><span class=\"kw-clinique\">Bronchiolite récidivante</span> + <span class=\"kw-clinique\">cassure pondérale</span></span> (tombé en annale).</td></tr>\n    <tr><td><strong>Respiratoire</strong></td><td><span class=\"kw-clinique\">Encombrement bronchique persistant</span>, <span class=\"kw-etio\">bronchiolites</span>/<span class=\"kw-etio\">bronchites asthmatiformes récidivantes</span> → <strong><span class=\"kw-etio\">bronchopathie chronique</span></strong> (<span class=\"kw-clinique\">toux chronique</span> + <span class=\"kw-clinique\">bronchorrhée</span>). Exacerbations : <span class=\"kw-clinique\">crachats mucopurulents</span>, <span class=\"kw-clinique\">dyspnée</span>. Tard : <strong><span class=\"kw-etio\">DDB</span></strong>, <span class=\"kw-etio\">emphysème</span>, <span class=\"kw-etio\">PNO</span>, <span class=\"kw-etio\">IRC</span>, <span class=\"kw-etio\">HTP</span>. <span class=\"kw-bio\">EFR</span> : <span class=\"kw-bio\">syndrome obstructif</span> non réversible puis distension.</td></tr>\n    <tr><td><strong><span class=\"kw-etio\">Infectieux</span></strong></td><td>Colonisation bronchique dès les 1ʳᵉˢ jours. Germes : <span class=\"kw-etio\"><em>H. influenzae</em></span>, <span class=\"kw-etio\"><em>S. aureus</em></span> initialement, puis <span class=\"kw-alerte\"><em>Pseudomonas aeruginosa</em> = tournant péjoratif</span>. <span class=\"kw-etio\">Mycobactéries atypiques</span>, <span class=\"kw-etio\">ABPA</span>.</td></tr>\n    <tr><td><strong>Digestif néonatal</strong></td><td><span class=\"kw-etio\">Iléus méconial</span>, <span class=\"kw-etio\">ictère cholestatique rétentionnel</span>.</td></tr>\n    <tr><td><strong>Pancréas</strong></td><td><span class=\"kw-etio\">Insuffisance pancréatique exocrine</span> (<span class=\"kw-chiffre\">95 %</span> des nourrissons) → <strong><span class=\"kw-clinique\">stéatorrhée</span></strong>, <strong><span class=\"kw-clinique\">retard pondéral puis statural</span></strong>, <span class=\"kw-clinique\">dénutrition</span> malgré <span class=\"kw-clinique\">hyperphagie</span>.</td></tr>\n    <tr><td><strong>Hépato-biliaire</strong></td><td><span class=\"kw-etio\">Lithiases</span>, <span class=\"kw-etio\">stéatose</span>, <span class=\"kw-etio\">cirrhose biliaire multifocale</span> (<span class=\"kw-chiffre\">5–15 %</span>) → <span class=\"kw-etio\">HTP</span> → <span class=\"kw-etio\">IHC</span>.</td></tr>\n    <tr><td><strong>Digestif autre</strong></td><td><span class=\"kw-etio\">RGO</span>, <span class=\"kw-etio\">prolapsus rectal</span>, <span class=\"kw-clinique\">constipation</span>, subocclusions (<span class=\"kw-etio\">IIA secondaire</span>).</td></tr>\n    <tr><td><strong>ORL</strong></td><td><span class=\"kw-etio\">Sinusite maxillaire</span>, <span class=\"kw-etio\">polypose nasale</span>.</td></tr>\n    <tr><td><strong>Endocrinien</strong></td><td><span class=\"kw-etio\">Intolérance au glucose</span>, <strong><span class=\"kw-etio\">diabète insulinodépendant</span></strong>.</td></tr>\n    <tr><td><strong>Métabolique</strong></td><td><span class=\"kw-alerte\">Déshydratation hyponatrémique avec coup de chaleur</span> ⭐ (annale).</td></tr>\n    <tr><td><strong>Génital</strong></td><td><span class=\"kw-clinique\">Retard pubertaire</span> ; <span class=\"kw-alerte\"><span class=\"kw-etio\">azoospermie obstructive bilatérale</span> (<span class=\"kw-chiffre\">98 %</span> des hommes)</span> par <span class=\"kw-etio\">atrésie des canaux déférents</span> ; <span class=\"kw-clinique\">hypofertilité féminine</span> (fertilité normale dans <span class=\"kw-chiffre\">80 %</span> des cas).</td></tr>\n    <tr><td><strong>Cardiaque</strong></td><td><span class=\"kw-etio\">Myocardiopathie non obstructive</span> (tardive).</td></tr>\n  </tbody>\n</table>"},{"id":"45-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes de la prise en charge de la mucoviscidose","frequence":1,"contenu":"\n<p>PEC <strong>multidisciplinaire</strong> coordonnée par un <span class=\"kw-def\">CRCM</span> régional, consultation <strong>tous les <span class=\"kw-chiffre\">3 mois</span></strong> + bilan annuel.</p>\n<table>\n  <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Respiratoire</strong></td><td>\n      <ul>\n        <li><span class=\"kw-ttt\">Kinésithérapie respiratoire quotidienne</span> (systématique).</li>\n        <li>Aérosols : <span class=\"kw-ttt\">rhDNase</span> ou <span class=\"kw-ttt\">sérum salé hypertonique</span> avant la kiné.</li>\n        <li>Hygiène domestique, éviction du tabac, éviction des viroses (1ʳᵉˢ années).</li>\n        <li><span class=\"kw-ttt\">OLD</span> si <span class=\"kw-etio\">IRC</span>, <span class=\"kw-ttt\">VNI</span> si <span class=\"kw-clinique\">hypercapnie</span>, <span class=\"kw-ttt\">transplantation pulmonaire</span> si IRC sévère.</li>\n      </ul>\n    </td></tr>\n    <tr><td><strong>Anti-<span class=\"kw-etio\">infectieux</span></strong></td><td><span class=\"kw-ttt\">ATB adaptée à l'<span class=\"kw-bio\">ECBC</span></span>, cure de <span class=\"kw-chiffre\">2–3 sem</span> (PO / inhalée / IV). Vaccinations : <span class=\"kw-ttt\">grippe annuelle</span>, <span class=\"kw-ttt\">hépatite A</span>, varicelle après <span class=\"kw-chiffre\">1 an</span>, <span class=\"kw-ttt\">pneumocoque 23-valences</span> après <span class=\"kw-chiffre\">2 ans</span> en complément du conjugué.</td></tr>\n    <tr><td><strong>Digestif</strong></td><td><span class=\"kw-ttt\">Opothérapie pancréatique</span> (extraits gastroprotégés). <span class=\"kw-ttt\">Acide ursodésoxycholique</span> pour l'atteinte hépato-biliaire.</td></tr>\n    <tr><td><strong>Nutritionnel</strong></td><td>Régime hypercalorique (<span class=\"kw-chiffre\">120–150 %</span>), pauvre en graisses. <span class=\"kw-alerte\"><span class=\"kw-ttt\">Vitamines liposolubles ADEK</span></span> ⭐ systématiques. <span class=\"kw-ttt\">Supplémentation sodée</span> (nourrisson, été, sport, <span class=\"kw-clinique\">fièvre</span>).</td></tr>\n    <tr><td><strong>Social / psychologique</strong></td><td><span class=\"kw-def\">ALD</span> <span class=\"kw-chiffre\">100 %</span>, PAI scolaire, <span class=\"kw-ttt\">soutien psychologique</span>, associations (<em>Vaincre la Mucoviscidose</em>).</td></tr>\n    <tr><td><strong><span class=\"kw-etio\">Génétique</span></strong></td><td><span class=\"kw-def\">Conseil génétique</span> au couple (risque récurrence <span class=\"kw-chiffre\">25 %</span>), <span class=\"kw-def\">DPN</span>/<span class=\"kw-def\">DPI</span> proposés.</td></tr>\n  </tbody>\n</table>"},{"id":"45-17","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","frequence":0,"contenu":"\n<table>\n  <thead><tr><th>Examen</th><th>Indication / rythme</th><th>Recherche</th></tr></thead>\n  <tbody>\n    <tr><td><strong><span class=\"kw-imagerie\">RXT face</span></strong></td><td><strong>Annuelle</strong> dans le bilan systématique du CRCM ; à toute exacerbation.</td><td><span class=\"kw-clinique\">Distension thoracique</span>, <span class=\"kw-imagerie\">syndrome bronchique</span>, <span class=\"kw-etio\">DDB</span>, <span class=\"kw-etio\">atélectasie</span>, <span class=\"kw-imagerie\">infiltrats</span>, <span class=\"kw-etio\">PNO</span>.</td></tr>\n    <tr><td><strong><span class=\"kw-imagerie\">TDM thoracique</span></strong></td><td>Devant signes d'évolutivité ou de complication (suspicion <span class=\"kw-etio\">DDB</span>, <span class=\"kw-etio\">ABPA</span>, <span class=\"kw-clinique\">hémoptysie</span>, <span class=\"kw-etio\">PNO</span>).</td><td><strong><span class=\"kw-etio\">DDB</span></strong> (forme cylindrique → kystique), <span class=\"kw-imagerie\">épaississements péri-bronchiques</span>, <span class=\"kw-imagerie\">impactions mucoïdes</span>.</td></tr>\n    <tr><td><strong><span class=\"kw-imagerie\">Échographie abdominale</span></strong></td><td>Bilan initial, <span class=\"kw-def\">surveillance</span> hépato-biliaire annuelle.</td><td><span class=\"kw-etio\">Stéatose</span>, <span class=\"kw-etio\">lithiases</span>, <span class=\"kw-etio\">cirrhose biliaire</span>, signes d'<span class=\"kw-etio\">HTP</span>, <span class=\"kw-imagerie\">pancréas</span>.</td></tr>\n    <tr><td><strong><span class=\"kw-imagerie\">TDM des sinus</span></strong></td><td><span class=\"kw-etio\">Polypose nasale</span> rebelle, <span class=\"kw-etio\">sinusite chronique</span>.</td><td>Polypes, opacification chronique.</td></tr>\n    <tr><td><strong><span class=\"kw-imagerie\">ASP</span></strong></td><td>Suspicion d'<span class=\"kw-etio\">iléus méconial</span> / subocclusion / <span class=\"kw-etio\">SOID</span>.</td><td><span class=\"kw-imagerie\">Niveaux hydroaériques</span>, <span class=\"kw-imagerie\">pneumopéritoine</span>.</td></tr>\n  </tbody>\n</table>"},{"id":"45-18","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","frequence":3,"contenu":"\n<p>Le diagnostic clinique est <strong>difficile</strong> : signes discrets et peu spécifiques, surtout chez le jeune enfant. <strong>À évoquer devant toute <span class=\"kw-def\">déficience intellectuelle non syndromique</span>.</strong></p>\n<table>\n  <thead><tr><th>Domaine</th><th>Signes (mutation complète, garçon)</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Neuro-développement / psychiatrie</strong></td><td>\n      <ul>\n        <li><strong><span class=\"kw-def\">Déficience intellectuelle</span> constante, modérée</strong> (QI <span class=\"kw-chiffre\">40–50</span>), <span class=\"kw-clinique\">troubles des apprentissages</span>.</li>\n        <li><span class=\"kw-clinique\">Retard psychomoteur</span> portant surtout sur le <span class=\"kw-alerte\">langage</span> ⭐ (acquisitions motrices peu altérées).</li>\n        <li>Troubles du comportement : <span class=\"kw-clinique\">hyperactivité</span>, <span class=\"kw-clinique\">impulsivité</span>, <span class=\"kw-clinique\">intolérance à la frustration</span>, <strong><span class=\"kw-clinique\">timidité avec fuite du regard</span></strong>.</li>\n        <li><span class=\"kw-clinique\">Troubles du sommeil</span>, <span class=\"kw-etio\">TSA</span> (<span class=\"kw-chiffre\">30–50 %</span>).</li>\n      </ul>\n    </td></tr>\n    <tr><td><strong>Dysmorphie</strong></td><td>S'affirme avec l'âge : <span class=\"kw-clinique\">visage allongé et étroit</span>, <span class=\"kw-clinique\">macrocéphalie</span>, <span class=\"kw-clinique\">front allongé</span>, <strong><span class=\"kw-clinique\">grandes oreilles décollées</span></strong>, <span class=\"kw-clinique\">menton long / prognathisme</span>, <span class=\"kw-clinique\">lèvres épaisses éversées</span>, <span class=\"kw-clinique\">palais ogival</span>, <span class=\"kw-clinique\">malpositions dentaires</span>.</td></tr>\n    <tr><td><strong>Après puberté</strong></td><td><strong><span class=\"kw-clinique\">Macro-orchidie</span></strong> (uniquement post-pubertaire).</td></tr>\n    <tr><td><strong>Autres</strong></td><td><span class=\"kw-etio\">Épilepsie</span>, <span class=\"kw-clinique\">hyperlaxité</span>, <span class=\"kw-etio\">prolapsus mitral</span>, <span class=\"kw-etio\">otites fréquentes</span>, <strong><span class=\"kw-clinique\">avance staturale</span></strong> ⭐, <span class=\"kw-clinique\">pieds plats</span>, <span class=\"kw-etio\">scoliose</span>, <span class=\"kw-etio\">RVU</span>, <span class=\"kw-clinique\">strabisme</span>, <span class=\"kw-clinique\">myopie</span>.</td></tr>\n    <tr><td><strong>Chez la fille</strong></td><td>Difficultés cognitives variables dans <span class=\"kw-chiffre\">50 %</span> des cas (<span class=\"kw-def\">inactivation aléatoire de l'X</span>).</td></tr>\n  </tbody>\n</table>\n<p><strong>Confirmation</strong> : <span class=\"kw-bio\">PCR fluorescente</span> du gène <em>FMR1</em> (nombre de <span class=\"kw-bio\">triplets CGG</span>) ± <strong><span class=\"kw-bio\">Southern / Western blot</span></strong> si grande expansion ou allèle unique chez la fille (<span class=\"kw-bio\">méthylation</span>). <span class=\"kw-alerte\">Le caryotype standard ne montre pas le X fragile.</span></p>"},{"id":"45-19","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les mécanismes génétiques dans le syndrome du X fragile (prémutation et mutation complète concernant l'X fragile)","frequence":5,"contenu":"\n<p>Gène <strong><em>FMR1</em></strong> (Fragile X Mental Retardation 1) — bras long du chromosome X (locus FRAXA) — code la <strong><span class=\"kw-def\">protéine FMRP</span></strong>, chaperonne d'ARNm essentielle à la <span class=\"kw-def\">plasticité synaptique</span>. Le 1ᵉʳ exon contient une répétition de <span class=\"kw-bio\">triplets CGG</span> dont l'expansion est <strong>instable</strong> et s'aggrave au fil des générations.</p>\n<table>\n  <thead><tr><th>Triplets CGG</th><th>État</th><th>ARNm</th><th>Protéine FMRP</th><th>Conséquence</th></tr></thead>\n  <tbody>\n    <tr><td><span class=\"kw-chiffre\">6 – 44</span> (moy. <span class=\"kw-chiffre\">30</span>)</td><td>Normal</td><td>—</td><td>—</td><td>Transmission stable</td></tr>\n    <tr><td><span class=\"kw-chiffre\">45 – 54</span></td><td>Intermédiaire</td><td>—</td><td>—</td><td>Expansion rare vers prémutation, jamais vers mutation</td></tr>\n    <tr><td><span class=\"kw-chiffre\">55 – ≤ 200</span> sans méthylation</td><td><strong><span class=\"kw-def\">Prémutation</span></strong></td><td>Présent → <span class=\"kw-clinique\">agrégats toxiques nucléaires</span></td><td>Synthèse normale</td><td><span class=\"kw-etio\">FXTAS</span> (H), <span class=\"kw-etio\">FXPOI</span> (F)</td></tr>\n    <tr><td><span class=\"kw-chiffre\">≥ 200</span> avec <span class=\"kw-bio\">méthylation</span></td><td><strong><span class=\"kw-def\">Mutation complète</span></strong></td><td>Absent (<span class=\"kw-bio\">hyperméthylation</span> → transcription bloquée)</td><td>Absente (H) / réduite (F)</td><td><span class=\"kw-clinique\">Syndrome de l</span>'X fragile</td></tr>\n  </tbody>\n</table>\n<p><strong>Transmission</strong> — <span class=\"kw-def\">hérédité liée à l'X dominante</span> (les femmes peuvent être symptomatiques) :</p>\n<table>\n  <thead><tr><th>Transmetteur</th><th>Particularités</th></tr></thead>\n  <tbody>\n    <tr><td><strong>Père prémuté</strong></td><td>Pas de modification de la taille. Toutes les filles atteintes (prémutées). <span class=\"kw-alerte\">Jamais de transmission père-fils</span>.</td></tr>\n    <tr><td><strong>Mère prémutée</strong></td><td><span class=\"kw-alerte\">Risque d'expansion vers la <span class=\"kw-def\">mutation complète</span></span> à la génération suivante, corrélé à la taille de la prémutation. Risque moindre si triplets AGG ; comparable à une mutée si déjà eu un enfant muté (<span class=\"kw-chiffre\">50 %</span>).</td></tr>\n    <tr><td><strong>Mère mutée complète</strong></td><td><span class=\"kw-chiffre\">50 %</span> de transmettre la mutation complète, quel que soit le sexe.</td></tr>\n  </tbody>\n</table>\n<p><em>Autres maladies par mutations instables à connaître :</em> <span class=\"kw-etio\">chorée de Huntington</span>, <span class=\"kw-etio\">dystrophie myotonique de Steinert</span>.</p>"},{"id":"45-20","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir penser à un syndrome de l'X fragile","frequence":2,"contenu":"\n<p>Le X fragile est la <strong>2ᵉ cause <span class=\"kw-etio\">génétique</span></strong> de <span class=\"kw-def\">déficience intellectuelle</span> après la <span class=\"kw-etio\">T21</span> et la <strong>1ʳᵉ cause monogénique / familiale</strong>.</p>\n<p><strong>À évoquer systématiquement devant :</strong></p>\n<ul>\n  <li><strong>Toute <span class=\"kw-def\">déficience intellectuelle non syndromique</span></strong> (recherche en 1ʳᵉ intention).</li>\n  <li><strong>Garçon avec <span class=\"kw-clinique\">retard de langage marqué</span></strong> + acquisitions motrices conservées.</li>\n  <li>ATCD familiaux de <span class=\"kw-def\">déficience intellectuelle</span> (surtout <strong>hérédité maternelle</strong>).</li>\n  <li>Tableau associant : <span class=\"kw-clinique\">grandes oreilles décollées</span>, <span class=\"kw-clinique\">visage allongé</span>, <span class=\"kw-clinique\">hyperlaxité</span>, <span class=\"kw-clinique\">troubles du comportement</span> avec timidité/fuite du regard, <span class=\"kw-etio\">TSA</span>.</li>\n  <li><span class=\"kw-clinique\">Macro-orchidie post-pubertaire</span>.</li>\n  <li><span class=\"kw-alerte\">Femme &lt; <span class=\"kw-chiffre\">40 ans</span> avec <span class=\"kw-etio\">insuffisance ovarienne prématurée</span></span> → rechercher une <strong>prémutation FMR1</strong> (<span class=\"kw-etio\">FXPOI</span> : <span class=\"kw-chiffre\">20 %</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">1 %</span> en popgénérale).</li>\n  <li>Homme avec <span class=\"kw-clinique\">ataxie cérébelleuse</span> + <span class=\"kw-clinique\">tremblements pseudo-parkinsoniens</span> + <span class=\"kw-clinique\">déclin cognitif</span> après <span class=\"kw-chiffre\">50 ans</span> → <span class=\"kw-etio\">FXTAS</span>.</li>\n</ul>\n<p><strong>Fréquence :</strong> <span class=\"kw-chiffre\">1/4 000</span> garçons, <span class=\"kw-chiffre\">1/5 000–1/8 000</span> filles.</p>\n<p><strong>Confirmation</strong> : <span class=\"kw-bio\">PCR fluorescente du gène FMR1</span> (à demander spécifiquement). <em>Pas de signe anténatal connu</em> (distracteur annale ⭐).</p>"},{"id":"45-21","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les différentes formes cliniques du syndrome de l'X Fragile","frequence":0,"contenu":"\n<p>Selon le statut moléculaire (<span class=\"kw-def\">prémutation</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">mutation complète</span>) et le sexe → 4 tableaux cliniques distincts.</p>\n<table>\n  <thead><tr><th>Statut</th><th>Sexe</th><th>Tableau clinique</th></tr></thead>\n  <tbody>\n    <tr><td rowspan=\"2\"><strong>Mutation complète</strong> (≥ <span class=\"kw-chiffre\">200</span> CGG, méthylé)</td><td>👦 Garçon</td><td><strong><span class=\"kw-clinique\">Syndrome de l</span>'X fragile</strong> : <span class=\"kw-def\">déficience intellectuelle</span> constante modérée, <span class=\"kw-clinique\">retard de langage majeur</span>, <span class=\"kw-clinique\">dysmorphie</span> (visage allongé, grandes oreilles), <span class=\"kw-clinique\">macro-orchidie</span> post-pubertaire, <span class=\"kw-etio\">TSA</span> (<span class=\"kw-chiffre\">30–50 %</span>), <span class=\"kw-etio\">épilepsie</span>.</td></tr>\n    <tr><td>👧 Fille</td><td>Difficultés cognitives variables (<span class=\"kw-chiffre\">50 %</span>), atténuées par l'<span class=\"kw-def\">inactivation aléatoire de l'X</span>. Pas de dysmorphie marquée.</td></tr>\n    <tr><td rowspan=\"2\"><strong>Prémutation</strong> (<span class=\"kw-chiffre\">55–199</span> CGG, non méthylé)</td><td>👦 Garçon</td><td><strong><span class=\"kw-etio\">FXTAS</span></strong> (Fragile X Tremor-Ataxia Syndrome) : maladie neurodégénérative progressive après <span class=\"kw-chiffre\">50 ans</span> — <span class=\"kw-clinique\">ataxie cérébelleuse</span>, <strong><span class=\"kw-clinique\">tremblements pseudo-parkinsoniens</span></strong>, <span class=\"kw-clinique\">myoclonies</span>, <span class=\"kw-clinique\">troubles anxieux</span>, <span class=\"kw-etio\">neuropathie sensitive</span>, <span class=\"kw-clinique\">déclin cognitif</span> → <span class=\"kw-etio\">démence</span>. <span class=\"kw-imagerie\">IRM</span> : <span class=\"kw-imagerie\">hypersignaux des pédoncules cérébelleux moyens</span> et/ou splénium du CC. Risque cumulé : <span class=\"kw-chiffre\">20 %</span> à <span class=\"kw-chiffre\">60 ans</span>, <span class=\"kw-chiffre\">75 %</span> &gt; <span class=\"kw-chiffre\">80 ans</span>. <strong>Pas de traitement curatif.</strong></td></tr>\n    <tr><td>👧 Fille</td><td><strong><span class=\"kw-etio\">FXPOI</span></strong> (<span class=\"kw-etio\">insuffisance ovarienne prématurée</span>) : <span class=\"kw-chiffre\">20 %</span> (<span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">1 %</span> en popgén). <span class=\"kw-ttt\">THS</span> jusqu'à l'âge moyen de la ménopause. <span class=\"kw-etio\">Hypothyroïdie</span> plus fréquente. <span class=\"kw-etio\">FXTAS</span> possible mais moins fréquent ⭐.</td></tr>\n  </tbody>\n</table>\n<p><strong>Signe négatif important :</strong> en cas de <span class=\"kw-def\">prémutation</span> seule, <em>pas de <span class=\"kw-def\">déficience intellectuelle</span></em> (à différencier de la mutation complète).</p>"}],"astuces":[{"type":"danger","titre":"Risque ≥ 1/50 → caryotype fœtal direct","contenu":"Au <span class=\"kw-def\">dépistage</span> combiné <span class=\"kw-etio\">T21</span>, retenir les 3 seuils :\n        <ul>\n          <li><strong><span class=\"kw-chiffre\">&lt; 1/1000</span></strong> : <span class=\"kw-def\">suivi</span> standard.</li>\n          <li><strong><span class=\"kw-chiffre\">1/1000 – 1/51</span></strong> : <span class=\"kw-ttt\"><strong>NIPT</strong></span> puis <span class=\"kw-ttt\">caryotype</span> si anormal.</li>\n          <li><strong><span class=\"kw-chiffre\">≥ 1/50</span></strong> : <span class=\"kw-ttt\">caryotype</span> d'emblée (ou <span class=\"kw-ttt\">NIPT</span> en 1ʳᵉ intention).</li>\n        </ul>\n        <span class=\"kw-alerte\">L'âge maternel seul n'est plus une indication de caryotype.</span>"},{"type":"danger","titre":"Bronchiolite récidivante + cassure pondérale = mucoviscidose ⭐","contenu":"Question d'annale classique. Autre <span class=\"kw-alerte\">red flag</span> : <span class=\"kw-alerte\"><strong>déshydratation hyponatrémique avec coup de chaleur</strong></span> chez un nourrisson. → <span class=\"kw-bio\">Test de la sueur</span> (<span class=\"kw-bio\">Cl⁻</span> &gt; <span class=\"kw-chiffre\">60 mmol/L</span>, confirmé sur <span class=\"kw-chiffre\">2</span> examens) + <span class=\"kw-bio\">biologie moléculaire CFTR</span>."},{"type":"danger","titre":"T21 — caryotype parental obligatoire si translocation","contenu":"<ul>\n        <li><strong><span class=\"kw-etio\">T21 libre</span></strong> (<span class=\"kw-chiffre\">95 %</span>) → caryotype parental <strong>inutile</strong>, récurrence ≈ <span class=\"kw-chiffre\">1 %</span>.</li>\n        <li><strong><span class=\"kw-etio\">T21 par translocation</span></strong> → <span class=\"kw-bio\">caryotype parental</span> <strong>obligatoire</strong> : <span class=\"kw-chiffre\">50 %</span> sont héritées d'un parent porteur d'une <span class=\"kw-def\">translocation équilibrée</span>.</li>\n        <li><span class=\"kw-def\">Translocation t(21;21)</span> chez un parent → récurrence <strong><span class=\"kw-chiffre\">100 %</span></strong>.</li>\n      </ul>"},{"type":"warn","titre":"Vitamines ADEK = systématique dans la mucoviscidose","contenu":"Supplémentation en <span class=\"kw-ttt\">vitamines liposolubles <strong>A, D, E, K</strong></span> ⭐ <em>toujours</em> prescrite, en raison de la <span class=\"kw-etio\">malabsorption</span> liée à l'<span class=\"kw-etio\">insuffisance pancréatique exocrine</span>. + <span class=\"kw-ttt\">opothérapie pancréatique gastroprotégée</span> + <span class=\"kw-ttt\">acide ursodésoxycholique</span> pour le foie."},{"type":"warn","titre":"Polysomnographie systématique à 4 ans dans la T21","contenu":"<span class=\"kw-alerte\"><span class=\"kw-etio\">SAOS</span> &gt; <span class=\"kw-chiffre\">50 %</span></span> chez l'enfant trisomique → <span class=\"kw-imagerie\"><strong>polysomnographie</strong></span> systématique à <span class=\"kw-chiffre\">4 ans</span>. Autre <span class=\"kw-def\">dépistage</span> annuel : <span class=\"kw-bio\">TSH/T4L</span> (<span class=\"kw-etio\">hypothyroïdie</span> <span class=\"kw-chiffre\">4–18 %</span>), <span class=\"kw-clinique\">audition</span>, ophtalmologie (<span class=\"kw-etio\">cataracte</span> <span class=\"kw-chiffre\">15 %</span>), clinique cœliaque.</p>"},{"type":"warn","titre":"Pseudomonas = tournant péjoratif de la mucoviscidose","contenu":"<span class=\"kw-def\">Suivi</span> <span class=\"kw-bio\">ECBC</span> régulier. Définition de colonisation chronique à <span class=\"kw-etio\"><em>P. aeruginosa</em></span> : présence pendant <strong>≥ <span class=\"kw-chiffre\">6 mois</span></strong> attestée par <strong>≥ <span class=\"kw-chiffre\">3</span> cultures positives à ≥ <span class=\"kw-chiffre\">1 mois</span> d'intervalle</strong>, sans signe direct d'infection. <span class=\"kw-ttt\">ATB ciblée <span class=\"kw-chiffre\">2–3 semaines</span></span>."},{"type":"info","titre":"X fragile — transmission père-fils impossible","contenu":"<span class=\"kw-def\">Hérédité liée à l'X dominante</span>. Le <strong>père prémuté</strong> transmet la <span class=\"kw-def\">prémutation</span> à <strong>toutes ses filles</strong> mais <strong>jamais à ses fils</strong>. Seule la <strong>mère</strong> peut faire l'expansion vers la <span class=\"kw-def\">mutation complète</span> (corrélée à la taille de sa prémutation)."},{"type":"info","titre":"Toute IOP < 40 ans → tester FMR1","contenu":"<strong><span class=\"kw-etio\">FXPOI</span></strong> (<span class=\"kw-etio\">insuffisance ovarienne prématurée</span>) concerne <span class=\"kw-chiffre\">20 %</span> des femmes prémutées (<span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">1 %</span> en popgén). Devant toute <span class=\"kw-etio\">IOP</span>, <strong>recherche systématique d'une <span class=\"kw-def\">prémutation FMR1</span></strong> par <span class=\"kw-bio\">PCR</span> (impact reproductif majeur pour la patiente et sa parentèle)."},{"type":"info","titre":"Triade T1 du dépistage T21","contenu":"Mémo : <strong>Â.É.M.</strong> = <strong>Â</strong>ge maternel + <strong>É</strong>chographie T1 (<span class=\"kw-imagerie\">clarté nucale</span> <span class=\"kw-chiffre\">&lt; 3 mm</span>) + <strong>M</strong>arqueurs sériques T1 (<span class=\"kw-bio\">PAPP-A</span> + <span class=\"kw-bio\">β-hCG libre</span>). Au T2 : <span class=\"kw-bio\">AFP</span> + <span class=\"kw-bio\">β-hCG</span> (± <span class=\"kw-bio\">œstriol</span>)."},{"type":"tip","titre":"Ig anti-D < 72 h après tout prélèvement ovulatoire","contenu":"Femme <strong><span class=\"kw-ttt\">RhD</span>-négatif</strong> + fœtus RhD+ ou inconnu → injection d'<span class=\"kw-ttt\">immunoglobulines anti-D dans les <span class=\"kw-chiffre\">72 h</span></span> suivant <span class=\"kw-ttt\">choriocentèse</span>, <span class=\"kw-ttt\">amniocentèse</span> ou <span class=\"kw-ttt\">cordocentèse</span>. Piège classique de QCM obstétrical-<span class=\"kw-etio\">génétique</span>."},{"type":"tip","titre":"Caryotype standard ≠ X fragile","contenu":"Le caryotype <strong>ne montre pas</strong> le X fragile (faux positifs/négatifs nombreux). Demander spécifiquement la <span class=\"kw-bio\"><strong>PCR fluorescente du gène FMR1</strong></span> ± <span class=\"kw-bio\">Southern/Western blot</span> pour la <span class=\"kw-bio\">méthylation</span>. Idem : la <span class=\"kw-etio\">T21 par mosaïque</span> peut nécessiter un caryotype sur plusieurs tissus."}],"liensGlobaux":[{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/enfant-vulnerable-genetique/syndrome-lx-fragile","label":"pedia-univ.fr"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/enfant-vulnerable-genetique/trisomie-21","label":"pedia-univ.fr"}],"cards":[{"i":"635ebb879e24","n":45,"o":"45-1","u":"Définition","t":"Connaître les règles de bases du conseil génétique","q":"Quelles sont les exigences spécifiques concernant l'arbre généalogique et l'information de la parentèle lors d'un conseil génétique ?","a":"<ul><li>Un <strong>arbre généalogique</strong> doit être réalisé de manière systématique sur au moins <strong>3 générations</strong>.</li><li>L'<strong>information de la parentèle</strong> est un devoir du patient si la maladie transmissible est grave et susceptible de mesures préventives ou curatives ; le médecin peut alors informer indirectement les apparentés via le patient.</li></ul>"},{"i":"680fbb8494dd","n":45,"o":"45-1","u":"Définition","t":"Connaître les règles de bases du conseil génétique","q":"Quelles sont les règles de communication et d'information encadrant le conseil génétique ?","a":"<ul><li>L'information doit être <strong>loyale, claire et appropriée</strong>.</li><li>Elle doit être <strong>non-directive</strong>, dans un cadre de <strong>neutralité bienveillante</strong>.</li><li>Le <strong>consentement écrit est obligatoire</strong> avant tout examen génétique, distinct pour chaque type d'examen (dépistage, échographie, examens invasifs).</li><li>Un <strong>délai de réflexion</strong> est nécessaire entre la consultation et le prélèvement génétique.</li><li>Le rendu des résultats se fait systématiquement <strong>en consultation</strong>, jamais par téléphone ni par courrier seul.</li></ul>"},{"i":"daaf6e8329fa","n":45,"o":"45-1","u":"Définition","t":"Connaître les règles de bases du conseil génétique","q":"Qu'est-ce que le conseil génétique en médecine ?","a":"<p>C'est une <strong>consultation médicale spécialisée</strong>, délivrée par un <strong>généticien clinique</strong>, visant à informer un individu ou un couple sur le <strong>risque de survenue ou de récurrence d'une maladie génétique</strong> et sur les <strong>options disponibles</strong> (diagnostic prénatal, diagnostic préimplantatoire, dépistage en cascade).</p>"},{"i":"fe7614bb9493","n":45,"o":"45-1","u":"Définition","t":"Connaître les règles de bases du conseil génétique","q":"Quelles sont les règles spécifiques concernant l'examen génétique chez le mineur et le diagnostic présymptomatique ?","a":"<ul><li>L'examen génétique du <strong>mineur</strong> est limité aux pathologies à <strong>expression pédiatrique</strong> pour lesquelles existe une prise en charge.</li><li>Le <strong>diagnostic présymptomatique</strong> (par exemple pour la maladie de Huntington) requiert un <strong>protocole multidisciplinaire</strong> impliquant généticien, psychologue et neurologue.</li></ul>"},{"i":"00f9f12c90cb","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quels sont les signes cliniques possibles au niveau des mains et des pieds évoquant une trisomie 21 en postnatal ?","a":"<ul><li><strong>Mains trapues</strong>, <strong>doigts courts</strong></li><li><strong>Clinodactylie du 5e doigt</strong> (brachymésophalangie)</li><li><strong>Pli palmaire transverse unique</strong> (présent chez 2/3 des Trisomiques 21)</li><li><strong>Pieds larges et courts</strong></li><li><strong>Signe de la sandale</strong> (espace entre l'hallux et le 2e orteil)</li><li><strong>Plantes plissées</strong></li></ul>"},{"i":"2ae6685cefe7","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"En dehors des atteintes spécifiques, quels sont les signes cutanés et de croissance fréquemment associés à la trisomie 21 en postnatal ?","a":"<ul><li><strong>Peau sèche</strong></li><li><strong>Hyperlaxité cutanée</strong></li><li><strong>Livedo</strong></li><li><strong>Retard statural</strong> (environ -2 DS)</li></ul>"},{"i":"33bb6b5fc52d","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quels sont les signes cliniques possibles au niveau du crâne et du visage évoquant une trisomie 21 en postnatal ?","a":"<ul><li><strong>Occiput plat</strong></li><li><strong>Petit périmètre crânien</strong> (environ -2 DS)</li><li><strong>Nuque courte et large</strong> avec excès de peau</li><li><strong>Visage rond et plat</strong></li></ul>"},{"i":"3dbe83b7168c","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quel est le signe clinique quasi-constant, bien que non spécifique, évoquant une trisomie 21 en postnatal ?","a":"<p>La quasi-constante de la trisomie 21 en postnatal est une <strong>hypotonie marquée</strong>, qui reste cependant non spécifique à cette pathologie.</p>"},{"i":"5ad7adcb2caa","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quels sont les signes cliniques possibles au niveau des yeux et des oreilles évoquant une trisomie 21 en postnatal ?","a":"<ul><li><strong>Hypertélorisme</strong></li><li><strong>Fentes palpébrales obliques en haut et en dehors</strong></li><li><strong>Épicanthus</strong></li><li><strong>Taches de Brushfield</strong> (au niveau des yeux)</li><li><strong>Petites oreilles rondes mal ourlées</strong></li></ul>"},{"i":"960258cc0e23","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quel est l'examen diagnostique de confirmation à réaliser en cas de suspicion clinique de trisomie 21 en postnatal ?","a":"<p>En cas de forte suspicion clinique de trisomie 21 en postnatal, le diagnostic est confirmé par la réalisation d'un <strong>caryotype standard</strong>. Une <strong>FISH 21</strong> peut être réalisée si une réponse rapide est nécessaire.</p>"},{"i":"99840e38963a","n":45,"o":"45-10","u":"Diagnostic positif","t":"Savoir évoquer le diagnostic clinique de trisomie 21 en postnatal","q":"Quels sont les signes cliniques possibles au niveau de la bouche et du nez évoquant une trisomie 21 en postnatal ?","a":"<ul><li><strong>Nez court</strong></li><li><strong>Ensellure nasale plate</strong></li><li><strong>Hypoplasie de l'os propre du nez</strong> (OPN)</li><li><strong>Petite bouche entrouverte</strong> (due à l'hypotonie)</li><li><strong>Langue protruse et plicaturée</strong></li><li><strong>Prognathisme</strong> (avec l'âge)</li></ul>"},{"i":"14f4f9237725","n":45,"o":"45-13","u":"Diagnostic positif","t":"Connaître les modalités du dépistage néonatal généralisé de la mucoviscidose","q":"Quel est l'objectif principal du dépistage néonatal de la mucoviscidose et quelles manifestations de la maladie peuvent être présentes dès la naissance ?","a":"<p>L'enjeu principal du dépistage néonatal de la mucoviscidose est la <strong>prise en charge précoce</strong> des manifestations pulmonaires et digestives, afin de <strong>ralentir l'évolution</strong> de la maladie et d'<strong>améliorer la survie</strong>. Dès la naissance, la mucoviscidose peut se manifester par un <strong>iléus méconial</strong> ou un <strong>ictère cholestatique rétentionnel</strong>.</p>"},{"i":"2f86cf6d070a","n":45,"o":"45-13","u":"Diagnostic positif","t":"Connaître les modalités du dépistage néonatal généralisé de la mucoviscidose","q":"Quelle est la méthode utilisée en France pour le dépistage néonatal généralisé de la mucoviscidose, et quand est-il réalisé ?","a":"<p>En France, depuis 2002, le dépistage néonatal généralisé de la mucoviscidose est réalisé via le <strong>test de Guthrie</strong>. Il est systématique et effectué environ <strong>72 heures de vie</strong>.</p>"},{"i":"a3091da38f62","n":45,"o":"45-13","u":"Diagnostic positif","t":"Connaître les modalités du dépistage néonatal généralisé de la mucoviscidose","q":"Quelle est la conduite à tenir si la Trypsine Immunoréactive (TIR) est élevée lors du dépistage néonatal de la mucoviscidose, et quelles sont les implications d'une éventuelle mutation du gène CFTR ?","a":"<p>Si la TIR est élevée, un <strong>diagnostic moléculaire</strong> est réalisé pour rechercher les <strong>29 mutations CFTR</strong> les plus fréquentes en France. Si <strong>aucune mutation</strong> n'est trouvée, un contrôle de la TIR est effectué à 3 semaines. Si <strong>une ou plusieurs mutations</strong> sont détectées, ou si la TIR est toujours élevée au contrôle, le nouveau-né est convoqué au <strong>CRCM régional</strong> pour un <strong>test de la sueur</strong>.</p>"},{"i":"b2da72b7c1d2","n":45,"o":"45-13","u":"Diagnostic positif","t":"Connaître les modalités du dépistage néonatal généralisé de la mucoviscidose","q":"Comment est effectué le prélèvement pour le test de Guthrie dans le cadre du dépistage néonatal de la mucoviscidose, et quelle est la première étape du dosage ?","a":"<p>Le prélèvement s'effectue par une <strong>goutte de sang au talon</strong> de l'enfant, déposée sur un <strong>papier buvard</strong>. Le dosage initial consiste à mesurer la <strong>Trypsine Immunoréactive (TIR) sanguine</strong>.</p>"},{"i":"2b4c64da082b","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Que signifie un résultat de « patient homozygote pour la même mutation » ou « hétérozygote composite » en biologie moléculaire pour la mucoviscidose ?","a":"<p>Cela signifie que le patient porte deux mutations pathogènes du gène <em>CFTR</em> :</p><ul><li><strong>Homozygote pour la même mutation :</strong> Il a hérité de la même mutation de ses deux parents.</li><li><strong>Hétérozygote composite :</strong> Il a hérité d'une mutation différente à chaque allèle du gène <em>CFTR</em>.</li></ul>"},{"i":"41e9c016a5c1","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Quel est l'examen de référence pour confirmer le diagnostic de mucoviscidose ?","a":"<p>L'examen de référence pour confirmer le diagnostic de mucoviscidose est le <strong>test de la sueur</strong>.</p>"},{"i":"78847716932d","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Comment interprète-t-on les résultats du test de la sueur dans le diagnostic de la mucoviscidose ?","a":"<ul><li><strong>Normal :</strong> Concentration de chlore (Cl⁻) <strong>&lt; 30 mmol/L</strong>.</li><li><strong>Intermédiaire :</strong> Concentration de chlore (Cl⁻) <strong>entre 30 et 59 mmol/L</strong>. Cela nécessite de répéter le test, de réaliser une biologie moléculaire et potentiellement des mesures électrophysiologiques en centre spécialisé.</li><li><strong>Pathologique :</strong> Concentration de chlore (Cl⁻) <strong>&gt; 60 mmol/L</strong>.</li></ul>"},{"i":"942a853847eb","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Comment procède-t-on à la recherche de mutations dans le cadre de la biologie moléculaire pour la mucoviscidose ?","a":"<ul><li>Initialement, une recherche des <strong>mutations les plus fréquentes</strong> est effectuée, notamment la mutation <strong>F508del +++</strong>.</li><li>Si nécessaire, une étude plus extensive est réalisée par <strong>séquençage complet du gène <em>CFTR</em></strong> pour identifier d'autres mutations.</li></ul>"},{"i":"a79e630b9cc5","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Quel est le rôle de la biologie moléculaire dans le diagnostic de la mucoviscidose ?","a":"<p>La biologie moléculaire est un complément nécessaire au test de la sueur. Elle vise à mettre en évidence une <strong>mutation pathogène sur chaque allèle</strong> du gène <em>CFTR</em>.</p>"},{"i":"d9676367b4fa","n":45,"o":"45-14","u":"Diagnostic positif","t":"Connaître les modalités de la confirmation diagnostique de la mucoviscidose","q":"Combien de tests positifs sont nécessaires pour affirmer le diagnostic de mucoviscidose par le test de la sueur ?","a":"<p>Le diagnostic de mucoviscidose est affirmé après l'obtention de <strong>deux examens positifs</strong> du test de la sueur.</p>"},{"i":"2eaf9404be18","n":45,"o":"45-17","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","q":"Quelle est l'indication de la TDM des sinus chez un patient mucoviscidosique, et que permet-elle de visualiser ?","a":"<p>La TDM des sinus est indiquée en cas de <strong>polypose nasale rebelle</strong> ou de <strong>sinusite chronique</strong> chez un patient atteint de mucoviscidose.</p><p>Elle permet de visualiser la présence de <strong>polypes</strong> et une <strong>opacification chronique des sinus</strong>.</p>"},{"i":"3c6a0bd7e1be","n":45,"o":"45-17","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","q":"Quelle est l'indication de la radiographie thoracique (RXT face) chez un patient atteint de mucoviscidose, et que recherche-t-on sur cet examen ?","a":"<p>La radiographie thoracique (RXT face) est indiquée :</p><ul><li>Annuellement, dans le cadre du bilan systématique au Centre de Ressources et de Compétences de la Mucoviscidose (CRCM).</li><li>À chaque exacerbation respiratoire.</li></ul><p>Elle permet de rechercher des signes tels que la <strong>distension thoracique</strong>, un <strong>syndrome bronchique</strong>, des <strong>bronchectasies</strong> (DDB), des <strong>atélectasies</strong>, des <strong>infiltrats pulmonaires</strong> ou un <strong>pneumothorax</strong> (PNO).</p>"},{"i":"61c2580d0277","n":45,"o":"45-17","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","q":"Dans quel contexte une radiographie de l'abdomen sans préparation (ASP) est-elle indiquée chez un patient atteint de mucoviscidose, et que recherche-t-on spécifiquement ?","a":"<p>Une radiographie de l'abdomen sans préparation (ASP) est indiquée en cas de suspicion d'<strong>iléus méconial</strong>, de <strong>subocclusion intestinale</strong> ou de <strong>syndrome d'obstruction intestinale distale</strong> (SOID) chez les patients atteints de mucoviscidose.</p><p>L'examen recherche la présence de <strong>niveaux hydroaériques</strong> ou un <strong>pneumopéritoine</strong>.</p>"},{"i":"9371b4571e32","n":45,"o":"45-17","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","q":"Dans quels contextes une TDM thoracique est-elle indiquée chez un patient atteint de mucoviscidose, et quels signes spécifiques recherche-t-on ?","a":"<p>Une TDM thoracique est indiquée devant des signes d'<strong>évolutivité</strong> ou de <strong>complication</strong> de la mucoviscidose, tels qu'une suspicion de <strong>bronchectasies</strong> (DDB), une <strong>aspergillose bronchopulmonaire allergique</strong> (ABPA), une <strong>hémoptysie</strong> ou un <strong>pneumothorax</strong> (PNO).</p><p>Cet examen recherche des signes comme des <strong>bronchectasies</strong> (de forme cylindrique à kystique), des <strong>épaississements péri-bronchiques</strong> et des <strong>impactions mucoïdes</strong>.</p>"},{"i":"f0ee2f5b8e03","n":45,"o":"45-17","u":"Examens complémentaires","t":"Connaître l'indication des examens d'imagerie devant une mucoviscidose","q":"Quand l'échographie abdominale est-elle indiquée dans la mucoviscidose, et quelles anomalies hépato-biliaires ou pancréatiques peuvent être détectées ?","a":"<p>L'échographie abdominale est indiquée lors du <strong>bilan initial</strong> et pour une <strong>surveillance hépato-biliaire annuelle</strong> chez les patients atteints de mucoviscidose.</p><p>Elle peut détecter des anomalies telles que la <strong>stéatose hépatique</strong>, des <strong>lithiases biliaires</strong>, une <strong>cirrhose biliaire</strong>, des signes d'<strong>hypertension portale</strong> (HTP) et des anomalies du <strong>pancréas</strong>.</p>"},{"i":"09f427b65cab","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Quelles sont les particularités cliniques du syndrome de l'X fragile chez la fille ?","a":"<p>Chez la fille, des <strong>difficultés cognitives variables</strong> sont présentes dans environ <strong>50% des cas</strong>, en raison de l'inactivation aléatoire de l'X.</p>"},{"i":"3bee343cb26b","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Quelles sont les autres manifestations cliniques non spécifiques pouvant être associées au syndrome de l'X fragile ?","a":"<ul><li>Épilepsie.</li><li><strong>Hyperlaxité</strong>.</li><li>Prolapsus mitral.</li><li>Otites fréquentes.</li><li><strong>Avance staturale</strong>.</li><li>Pieds plats.</li><li>Scoliose.</li><li>Reflux vésico-urétéral (RVU).</li><li>Strabisme, myopie.</li></ul>"},{"i":"704e8662ee2b","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Dans quel contexte clinique doit-on évoquer un syndrome de l'X fragile, en particulier chez un jeune enfant ?","a":"<p>Il doit être évoqué devant toute <strong>déficience intellectuelle non syndromique</strong>. Le diagnostic clinique est difficile chez le jeune enfant en raison de signes discrets et peu spécifiques.</p>"},{"i":"72b323ec8907","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Quels sont les principaux signes neuro-développementaux et psychiatriques du syndrome de l'X fragile chez le garçon porteur d'une mutation complète ?","a":"<ul><li><strong>Déficience intellectuelle constante</strong>, le plus souvent modérée (QI 40–50), avec des troubles des apprentissages.</li><li>Un <strong>retard psychomoteur</strong>, particulièrement marqué sur le <strong>langage</strong>.</li><li>Des troubles du comportement, tels que l'<strong>hyperactivité</strong>, l'impulsivité, l'intolérance à la frustration, la timidité avec fuite du regard.</li><li>Des troubles du sommeil.</li><li>Un trouble du spectre de l'autisme (TSA) dans 30 à 50% des cas.</li></ul>"},{"i":"acf9a039d2f3","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Quel signe physique est spécifique du syndrome de l'X fragile et apparaît après la puberté chez le garçon ?","a":"<p>Le signe spécifique post-pubertaire est la <strong>macro-orchidie</strong>.</p>"},{"i":"ae854c593f7f","n":45,"o":"45-18","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic clinique du syndrome du X Fragile","q":"Quelles sont les caractéristiques de la dysmorphie faciale associée au syndrome de l'X fragile, et à quel âge apparaissent-elles principalement ?","a":"<p>La dysmorphie faciale s'affirme <strong>avec l'âge</strong> et inclut :</p><ul><li>Un <strong>visage allongé et étroit</strong>.</li><li>Une <strong>macrocéphalie</strong>.</li><li>Un front allongé.</li><li>Des <strong>grandes oreilles décollées</strong>.</li><li>Un menton long ou <strong>prognathisme</strong>.</li><li>Des lèvres épaisses éversées.</li><li>Un palais ogival et des malpositions dentaires.</li></ul>"},{"i":"4ac6978b75f6","n":45,"o":"45-20","u":"Diagnostic positif","t":"Savoir penser à un syndrome de l'X fragile","q":"Quand faut-il évoquer un syndrome de l'X fragile chez un homme de plus de 50 ans ?","a":"<p>Chez un homme de plus de 50 ans, il faut évoquer le syndrome de l'X fragile (FXTAS) devant l'association d'une <strong>ataxie cérébelleuse</strong>, de <strong>tremblements pseudo-parkinsoniens</strong> et d'un <strong>déclin cognitif</strong>.</p>"},{"i":"54014b535ecf","n":45,"o":"45-20","u":"Diagnostic positif","t":"Savoir penser à un syndrome de l'X fragile","q":"Comment confirmer le diagnostic de syndrome de l'X fragile ?","a":"<p>Le diagnostic de syndrome de l'X fragile est confirmé par une <strong>PCR fluorescente du gène FMR1</strong>, qui doit être demandée spécifiquement.</p>"},{"i":"6d056b3756f2","n":45,"o":"45-20","u":"Diagnostic positif","t":"Savoir penser à un syndrome de l'X fragile","q":"Quand faut-il évoquer un syndrome de l'X fragile chez une femme ?","a":"<p>Il faut évoquer un syndrome de l'X fragile chez une femme de moins de 40 ans présentant une <strong>insuffisance ovarienne prématurée</strong> (FXPOI), car une <strong>prémutation FMR1</strong> est retrouvée dans 20% des cas.</p>"},{"i":"773919f98672","n":45,"o":"45-20","u":"Diagnostic positif","t":"Savoir penser à un syndrome de l'X fragile","q":"Quand faut-il évoquer un syndrome de l'X fragile chez un garçon ?","a":"<p>Il faut évoquer un syndrome de l'X fragile chez un garçon systématiquement devant :</p><ul><li>Toute <strong>déficience intellectuelle non syndromique</strong> (recherche en première intention).</li><li>Un <strong>retard de langage marqué</strong> avec des acquisitions motrices conservées.</li><li>Des <strong>antécédents familiaux de déficience intellectuelle</strong> (particulièrement en cas d'hérédité maternelle).</li><li>Un tableau clinique associant : <strong>grandes oreilles décollées</strong>, <strong>visage allongé</strong>, <strong>hyperlaxité</strong>, <strong>troubles du comportement</strong> avec timidité/fuite du regard, ou un <strong>trouble du spectre autistique</strong> (TSA).</li><li>Une <strong>macro-orchidie</strong> post-pubertaire.</li></ul>"},{"i":"96c6cdc84f02","n":45,"o":"45-20","u":"Diagnostic positif","t":"Savoir penser à un syndrome de l'X fragile","q":"Quelle est la place du syndrome de l'X fragile comme cause de déficience intellectuelle ?","a":"<p>Le syndrome de l'X fragile est la <strong>deuxième cause génétique de déficience intellectuelle</strong> après la trisomie 21, et la <strong>première cause monogénique/familiale</strong>.</p>"},{"i":"1bfa244f75f2","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Quelles sont les considérations éthiques majeures concernant la décision d'Interruption Médicale de Grossesse (IMG) pour une affection génétique ?","a":"<p>La décision d'<strong>Interruption Médicale de Grossesse (IMG)</strong> impose le <strong>respect du choix du couple</strong> par le médecin, en adoptant une position de <strong>neutralité</strong> et en prenant en compte les aspects <strong>culturels, philosophiques ou religieux</strong> qui peuvent influencer cette décision.</p>"},{"i":"79f1b0a62c19","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Quels principes éthiques fondamentaux doivent guider l'attitude du médecin lors d'un conseil génétique ?","a":"<p>Lors d'un conseil génétique, le médecin doit faire preuve d'<strong>autonomie du patient</strong>, de <strong>neutralité</strong> et de <strong>non-directivité</strong> afin de respecter les choix et convictions du consultant sans influence indue.</p>"},{"i":"834615ee5c37","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Comment le cadre légal concilie-t-il le secret médical et l'information des apparentés en cas de risque génétique grave ?","a":"<p>En cas de risque génétique grave pour les apparentés, la <strong>loi de bioéthique</strong> encadre le conflit entre le <strong>secret médical</strong> et l'information des membres de la famille, permettant dans certains cas une information à condition que le patient ait donné son consentement ou qu'une procédure spécifique soit respectée.</p>"},{"i":"965947c2c785","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Sous quelles conditions éthiques et légales l'examen génétique chez un mineur est-il autorisé ?","a":"<p>L'examen génétique chez le mineur est limité aux pathologies à <strong>expression pédiatrique</strong> pour lesquelles une <strong>prise en charge (PEC) est disponible</strong>, dans le but de ne pas le priver de son <strong>avenir de choix</strong> concernant les informations de santé le concernant.</p>"},{"i":"cdc424e1b95f","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Quelle est la particularité éthique du diagnostic présymptomatique des maladies génétiques sans traitement, comme la maladie de Huntington ?","a":"<p>Pour les maladies sans traitement, tel que la <strong>maladie de Huntington</strong>, le diagnostic présymptomatique nécessite un <strong>protocole structuré multidisciplinaire</strong>, incluant un <strong>délai de réflexion long</strong> et un <strong>accompagnement psychologique</strong>, afin de gérer l'impact d'une telle information sur la vie du patient.</p>"},{"i":"d47ca94f281e","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Quels sont les enjeux éthiques soulevés par le dépistage de masse des maladies génétiques, tels que celui de la Trisomie 21 ?","a":"<p>Le dépistage de masse, notamment de la <strong>Trisomie 21</strong>, soulève la question de l'<strong>eugénisme</strong> et du risque de <strong>dérive sociétale</strong>, en interrogeant la finalité d'élimination de certaines maladies ou conditions génétiques.</p>"},{"i":"e15c5782fc42","n":45,"o":"45-3","u":"Définition","t":"Connaître les questions éthiques en jeu dans le conseil génétique","q":"Quel est l'enjeu éthique principal lié à la confidentialité des données génétiques ?","a":"<p>L'enjeu éthique principal de la confidentialité des données génétiques concerne leur <strong>protection légale</strong> vis-à-vis d'entités telles que les <strong>assurances et les employeurs</strong>, afin d'éviter toute discrimination ou utilisation abusive.</p>"},{"i":"5387ec678f83","n":45,"o":"45-5","u":"Diagnostic positif","t":"Connaître les modalités du dépistage anténatal de trisomie 21","q":"Quelle est la conduite à tenir en fonction du risque combiné de trisomie 21 calculé lors du dépistage anténatal ?","a":"<p>La conduite à tenir dépend du niveau de risque combiné :</p><ul><li>Si le risque est <strong>&lt; 1/1000</strong> : un <strong>suivi habituel</strong> est mis en place.</li><li>Si le risque est entre <strong>1/1000 et 1/51</strong> : un <strong>NIPT</strong> (ADN libre circulant) est proposé. Si le NIPT est anormal, un <strong>caryotype fœtal</strong> est ensuite réalisé.</li><li>Si le risque est <strong>≥ 1/50</strong> : un <strong>caryotype fœtal</strong> est proposé d'emblée, ou un NIPT en première intention si la femme le souhaite.</li></ul>"},{"i":"56836d51558a","n":45,"o":"45-5","u":"Diagnostic positif","t":"Connaître les modalités du dépistage anténatal de trisomie 21","q":"Comment le dépistage anténatal de la trisomie 21 est-il proposé aux femmes enceintes en France ?","a":"<p>Le dépistage anténatal de la trisomie 21 est <strong>systématiquement proposé</strong> à toute femme enceinte, nécessitant son <strong>consentement écrit</strong>.</p>"},{"i":"80a50a432ce8","n":45,"o":"45-5","u":"Diagnostic positif","t":"Connaître les modalités du dépistage anténatal de trisomie 21","q":"Quelles sont les modalités du dépistage de la trisomie 21 si les marqueurs sériques du 1er trimestre n'ont pas pu être réalisés ou interprétés ?","a":"<p>Si les marqueurs du 1er trimestre ne sont pas interprétables (ex: échographie T1 non faite par un échographiste agréé, ou patiente vue au laboratoire après 14 SA), seuls les <strong>marqueurs sériques du 2ème trimestre non combinés</strong> (AFP + β-hCG ou hCG totales ± œstriol non conjugué) peuvent être utilisés, mais leur performance est moindre pour le dépistage de la trisomie 21.</p>"},{"i":"c52c4076a5f9","n":45,"o":"45-5","u":"Diagnostic positif","t":"Connaître les modalités du dépistage anténatal de trisomie 21","q":"Quels sont les trois paramètres utilisés pour le calcul combiné du risque de trisomie 21 au premier trimestre de la grossesse ?","a":"<p>Les trois paramètres utilisés pour le calcul combiné du risque de trisomie 21 sont :</p><ul><li>L'<strong>âge maternel</strong>.</li><li>L'<strong>échographie du 1er trimestre</strong> (entre 11 SA et 13 SA + 6 jours) évaluant la <strong>clarté nucale</strong> et recherchant un hygroma colli.</li><li>Les <strong>marqueurs sériques maternels du 1er trimestre</strong> : la <strong>PAPP-A</strong> et la <strong>β-hCG libre</strong>.</li></ul>"},{"i":"1bc4d68289e9","n":45,"o":"45-9","u":"Suivi et/ou pronostic","t":"Connaître l'évolution de la trisomie 21","q":"Quelles sont les atteintes ORL, ophtalmologiques, hématologiques et ostéoarticulaires les plus importantes chez les patients trisomiques 21 ?","a":"<ul><li><strong>ORL :</strong> Infections ORL récidivantes (60 %), <strong>surdité (45-75 %) avec dépistage annuel</strong>.</li><li><strong>Ophtalmologique :</strong> Strabisme et myopie (60 %), <strong>cataracte (15 %)</strong> nécessitant un examen annuel puis tous les 3 ans à l'âge adulte.</li><li><strong>Hématologique :</strong> Hyperleucocytose néonatale, et un risque accru de <strong>leucémie aiguë myéloïde (LAM) (1 %, risque multiplié par 10)</strong>.</li><li><strong>Ostéoarticulaire :</strong> <strong>Instabilité C1/C2</strong> (nécessitant une prudence lors de l'intubation), pieds plats valgus, ostéoporose à l'âge adulte.</li></ul>"},{"i":"4a0deae4c459","n":45,"o":"45-9","u":"Suivi et/ou pronostic","t":"Connaître l'évolution de la trisomie 21","q":"Comment la trisomie 21 affecte-t-elle la fertilité et le processus de vieillissement ?","a":"<ul><li><strong>Fertilité :</strong> Les <strong>femmes ont une fertilité normale</strong> (avec un risque de transmission de 1/3), tandis que les <strong>hommes présentent une stérilité dans 98 % des cas</strong>.</li><li><strong>Vieillissement :</strong> Il est <strong>précoce, anticipé d'environ 30 ans</strong>, se manifestant par une cataracte sénile précoce, de l'arthrose et une fatigabilité accrue.</li></ul>"},{"i":"595a0ea258b2","n":45,"o":"45-9","u":"Suivi et/ou pronostic","t":"Connaître l'évolution de la trisomie 21","q":"Quelle est l'espérance de vie actuelle pour une personne atteinte de trisomie 21 et qu'est-ce qui a permis cette amélioration ?","a":"<p>L'espérance de vie actuelle pour une personne atteinte de trisomie 21 est <strong>supérieure à 50 ans</strong>. Cette amélioration est due aux progrès de la prise en charge, notamment la chirurgie des cardiopathies (particulièrement des <strong>canaux atrio-ventriculaires - CAV</strong>), l'antibiothérapie et le suivi multidisciplinaire.</p>"},{"i":"cf1e000a308a","n":45,"o":"45-9","u":"Suivi et/ou pronostic","t":"Connaître l'évolution de la trisomie 21","q":"Quelles sont les principales manifestations neurologiques et cognitives associées à la trisomie 21 ?","a":"<ul><li><strong>Cognitif :</strong> Déficience intellectuelle variable (QI moyen d'environ 45, plage de 25 à 80), étant la <strong>première cause génétique de déficience intellectuelle</strong>. La lecture et l'écriture sont possibles pour 2/3 des individus.</li><li><strong>Langage :</strong> Retard de langage marqué.</li><li><strong>Neurologique :</strong> Risque élevé de <strong>maladie d'Alzheimer chez 50 % des patients après 40 ans</strong>, et épilepsie (1-10 %, dont le syndrome de West).</li></ul>"},{"i":"ef80ee2c64e6","n":45,"o":"45-9","u":"Suivi et/ou pronostic","t":"Connaître l'évolution de la trisomie 21","q":"Quelles sont les complications les plus fréquentes de la trisomie 21 concernant les systèmes cardiaque, digestif et endocrinien ?","a":"<ul><li><strong>Cardiaque :</strong> Les <strong>canaux atrio-ventriculaires (CAV) sont les plus fréquents (50 % des cardiopathies)</strong>, mais aussi tétralogie de Fallot, communications inter-ventriculaires (CIV) et inter-auriculaires (CIA).</li><li><strong>Digestif :</strong> Atrésie duodénale (10 %), imperforation anale, maladie de Hirschsprung (1 %), et maladie cœliaque (5 %).</li><li><strong>Endocrinien :</strong> <strong>Hypothyroïdie ou thyroïdite (4-18 %)</strong> nécessitant un dépistage annuel. Diabète de type 1 (1 %) et diabète de type 2 (lié à l'obésité, dépistage adulte). Présence d'une obésité chez 30-50 % des individus.</li></ul>"}]};